# Stories for albums 701–750 (long format agreed with the owner: three paragraphs + a listening tip,
# ~220–230 words per story (min ~210), three picks with ~12-word notes). Original Hebrew; facts checked on the web, uncertain ones softened.
# Used by tools/batches/build_701_750.py; later edits: python3 tools/apply_stories.py stories_701_750
STORIES = {}
def add(n, story, picks): STORIES[n] = {'story': story, 'picks': picks}

add(701, [
'''בסוף שנות השמונים U2 היו אחת הלהקות הגדולות בעולם, אחרי The Joshua Tree (אלבום 608), אבל גם עייפו מהדימוי הרציני שלהם, והביקורות על הסרט והאלבום Rattle and Hum פגעו בהם. בסוף 1990 הם נסעו לברלין, ממש אחרי נפילת החומה, כדי להקליט באולפני האנזה, שבהם הקליט דייוויד בואי את "Heroes" (אלבום 383). העבודה שם הייתה קשה, והלהקה כמעט התפרקה מרוב ויכוחים. מה שהציל אותם היה שיר אחד, One, שנולד כמעט במקרה מתוך אלתור באולפן. Achtung Baby יצא בסוף 1991, בהפקתם של דניאל לנואה ובריאן אינו.''',
'''הסאונד השתנה לגמרי: גיטרות מעוותות ומלוכלכות, תופים עם קצב של מוזיקת ריקודים, צלילים תעשייתיים, ובונו ששר לפעמים בקול נמוך ואירוני ולא רק בקריאות גדולות. Zoo Station הפותח נשמע כמו רכבת מקולקלת שנכנסת לתחנה. Mysterious Ways קצבי, פאנקי ומלא חושניות, ו־The Fly הוא דמות חדשה של בונו, כוכב רוק במשקפי שמש גדולים. בתוך כל הרעש הזה מסתתרים שירי אהבה ופרידה כואבים ואישיים, כמו So Cruel ו־Love Is Blindness, שנכתבו בתקופה של משברים בחיי חברי הלהקה.''',
'''האלבום הוכיח שלהקה ענקית יכולה להמציא את עצמה מחדש בלי לאבד את הקהל שלה. אחריו יצאה הלהקה למסע ההופעות Zoo TV, עם עשרות מסכי טלוויזיה ענקיים, שידורים חיים ושיחות טלפון מהבמה, שהיה אחד המופעים החדשניים של התקופה. One הפך לאחד השירים האהובים של שנות התשעים, ושרים אותו עד היום בחתונות ובהלוויות כאחד.''',
'''שמעו את האלבום ברצף, ושימו לב לניגוד בין הרעש של הצד הראשון לבין השקט העצוב של השירים האחרונים. ואחר כך חזרו ל־War (אלבום 527), ותשמעו כמה רחוק הלהקה הגיעה בשמונה שנים.''',
], [
('One', 'שיר על שני אנשים שקשה להם יחד ובלעדיו, שנולד מאלתור באולפן והציל את הלהקה.'),
('Mysterious Ways', 'קצב פאנקי וחושני, גיטרה מקפצת ובונו בשיא הקסם, אחד השירים הכי רקידים שלהם.'),
('Zoo Station', 'הפותח, גיטרות מעוותות ותופים מכניים, כמו הכרזה שהלהקה הישנה כבר לא כאן.'),
])

add(702, [
'''הקיי־אל־אף היו צמד מוזר ושובב מלונדון: ביל דראמונד, איש עסקי מוזיקה סקוטי, וג׳ימי קוטי, מוזיקאי ואמן. בסוף שנות השמונים הם הוציאו תקליטים בשמות שונים, חיקו ודגמו שירים של אחרים בלי רשות, ואפילו כתבו ספר הדרכה מלא הומור בשם The Manual, שמסביר איך להגיע למקום הראשון במצעד בקלות. ב־1990 וב־1991 הם הוציאו סדרה של להיטי ריקודים ענקיים, ו־The White Room, שיצא ב־1991, אסף אותם לאלבום אחד, שהם כינו בצחוק "האוס של אצטדיונים".''',
'''המוזיקה גדולה, צבעונית ומלאת אנרגיה: קצב האוס חזק, סינתיסייזרים ענקיים, מקהלות, קולות של קהל מריע, סירנות ודגימות מכל עבר. 3 a.m. Eternal, הלהיט הגדול שלהם, מגיע עם ראפ של ריקרדו דה פורס וקריאות של קהל, כאילו הוקלט בהופעה, ולמעשה הכל נבנה באולפן. What Time Is Love? הוא המנון לרחבת הריקודים, עם ריף סינתיסייזר שחוזר שוב ושוב עד שהוא נכנס לגוף. Last Train to Trancentral הוא נסיעה מהירה ברכבת דמיונית, ובסוף האלבום יש שירים רגועים וחלומיים יותר, כמו Build a Fire.''',
'''הקיי־אל־אף נודעו גם בתעלולים שלהם. בטקס פרסי הבריט ב־1992 הם הופיעו עם להקת פאנק רועשת, ירו כדורי סרק לעבר הקהל, ומיד אחר כך הודיעו שהם פורשים ומחקו את כל הקטלוג שלהם מהחנויות. כמה שנים אחר כך הם אפילו שרפו מיליון לירות שטרלינג משלהם, כמחאה וכמעשה אמנות.''',
'''שמעו את 3 a.m. Eternal בווליום גבוה, ודמיינו אצטדיון שלם רוקד. ואחר כך שמעו את Ninety של 808 סטייט (אלבום 651), כדי לשמוע את הצד השקט והעמוק יותר של אותה סצנה.''',
], [
('3 a.m. Eternal', 'הלהיט הגדול, האוס ענק עם ראפ, מקהלות וקריאות של קהל שלא באמת היה שם.'),
('What Time Is Love?', 'המנון לרחבה, עם ריף סינתיסייזר עיקש שחוזר שוב ושוב עד שהוא נכנס לגוף.'),
('Last Train to Trancentral', 'נסיעה מהירה ברכבת דמיונית, עם קצב סוחף, מקהלה וצפירות של קטר.'),
])

add(703, [
'''מסיב אטאק נולדו בבריסטול, עיר נמל במערב אנגליה, מתוך קבוצה של תקליטנים, ראפרים ואמני גרפיטי שנקראה הוויילד באנץ׳ ונהגה לנגן במסיבות. שלושת חבריה המרכזיים היו רוברט דל נאחה, הידוע בשם 3D, גרנט מרשל, המכונה דאדי ג׳י, ואנדרו ווולס, המכונה מאשרום. Blue Lines, אלבום הבכורה שלהם, יצא ב־1991, ונעזר בזמרים אורחים: שרה נלסון, זמר הרגאיי הוותיק הוראס אנדי, וראפר צעיר בשם טריקי, שהפך מאוחר יותר לכוכב בעצמו. נינה צ׳רי ובן זוגה, המפיק קמרון מקוויי, תמכו בהם ועזרו להם להשלים את העבודה.''',
'''המוזיקה איטית, עמוקה ומלאה באווירה: קצבים של היפ הופ, בס כבד של רגאיי ודאב, דגימות של סול ישן, וקולות רכים שמרחפים מעל הכל. Unfinished Sympathy הוא הלב של האלבום: שרה נלסון שרה על אהבה שלא נגמרה, מעל קצב איטי ותזמורת כלי מיתר שלמה, שהפך אותו לאחד השירים הגדולים של שנות התשעים. Safe from Harm נפתח בבס מפורסם ומהפנט, ו־One Love ו־Hymn of the Big Wheel מביאים את הקול החם והשקט של הוראס אנדי. יש גם גרסה רכה ומקסימה ל־Be Thankful for What You've Got של ויליאם דבוהן.''',
'''Blue Lines נחשב לאלבום שבו נולד הטריפ הופ, הסגנון שהגיע מבריסטול והשפיע על פורטיסהד, על טריקי ועל מוזיקה אלקטרונית רבה בשנים הבאות. בזמן מלחמת המפרץ הלהקה קיצרה לזמן מה את שמה ל"מסיב", כדי לא להישמע כמו שם של מתקפה צבאית.''',
'''זה אלבום של לילה מאוחר ואורות של עיר. שמעו את Unfinished Sympathy באוזניות, ושימו לב לרגע שבו כלי המיתר נכנסים ולוקחים את השיר למקום אחר לגמרי.''',
], [
('Unfinished Sympathy', 'שרה נלסון ותזמורת כלי מיתר מעל קצב איטי, אחד השירים הגדולים של העשור.'),
('Safe from Harm', 'הפותח, עם בס מהפנט, שירה חמה של שרה נלסון וראפ שקט ומאיים.'),
('One Love', 'הוראס אנדי שר בקול גבוה ושביר על אהבה, מעל קצב איטי ועמוק.'),
])

add(704, [
'''פריימל סקרים היא להקה מגלזגו, שבראשה עומד בובי גילספי, שהיה קודם המתופף של הג׳יזס אנד מרי צ׳יין בתקופת Psychocandy (אלבום 559). בסוף שנות השמונים הם ניגנו רוקנרול בסגנון הרולינג סטונס, ולא ממש הצליחו. ואז הם גילו את סצנת מסיבות האסיד האוס, והכל השתנה. התקליטן אנדרו ות׳רול לקח שיר שלהם, I'm Losing More Than I'll Ever Have, והפך אותו לשיר ריקוד בשם Loaded, עם קול מתוך סרט ישן של פיטר פונדה. השיר הפך ללהיט, ועליו נבנה Screamadelica, שיצא ב־1991.''',
'''האלבום מחבר בין רוק, גוספל, סול, דאב ומוזיקת מסיבות, ובכל שיר שולט צבע אחר. Movin' On Up הפותח הוא רוקנרול שמח בסגנון הסטונס, עם מקהלת גוספל, והוא הופק על ידי ג׳ימי מילר, שהפיק בזמנו את הסטונס עצמם. Loaded ו־Come Together הם שירי מסיבה ארוכים, עם פסנתר, קולות נשיים ותחושה של שמחה גדולה. Higher Than the Sun, שהופק עם האורב, מרחף כמו חלום, ו־Damaged הוא בלדה עייפה ויפה. Don't Fight It, Feel It מביא את קולה החזק של הזמרת דניס ג׳ונסון.''',
'''Screamadelica זכה בשנת 1992 בפרס מרקורי הראשון, הפרס החשוב לאלבום הבריטי של השנה. הוא נחשב לאלבום שהצליח יותר מכל לחבר בין עולם הרוק לבין תרבות המסיבות של סוף שנות השמונים, ועטיפתו האדומה והצהובה, עם השמש המחייכת, הפכה לאחד הסמלים של התקופה.''',
'''שמעו את Movin' On Up ואחריו את Loaded, ותשמעו את שני הצדדים של הלהקה. ואחר כך נסו את Pills 'n' Thrills and Bellyaches של הפי מאנדייז (אלבום 673), עוד תקליט מאותה סצנה שמחה.''',
], [
('Movin\' On Up', 'הפותח, רוקנרול שמח עם מקהלת גוספל, כמו שיר אבוד של הרולינג סטונס.'),
('Loaded', 'השיר שהתחיל הכל, קצב ריקוד, פסנתר וקול של פיטר פונדה מתוך סרט ישן.'),
('Higher Than the Sun', 'שיר מרחף וחלומי, שהופק עם האורב ונשמע כמו שקיעה ארוכה וחמה.'),
])

add(705, [
'''טינאייג׳ פנקלאב היא להקה מגלזגו, שקמה ב־1989 סביב שלושה כותבי שירים: נורמן בלייק, ריימונד מקגינלי וג׳רארד לאב, וכל אחד מהם שר את השירים שכתב. הם אהבו את הבירדס ואת ביג סטאר (אלבום 242), וגם את רעש הגיטרות של להקות האינדי האמריקאיות. Bandwagonesque, האלבום השלישי שלהם, יצא ב־1991, והופק על ידי דון פלמינג. בארצות הברית בחר בו מגזין ספין כאלבום השנה, לפני Nevermind של נירוונה (אלבום 685), החלטה שהפתיעה רבים ועדיין מעוררת ויכוחים.''',
'''המוזיקה היא פופ רוק חם ומתוק, עם גיטרות מזמזמות ורועשות, הרמוניות קוליות רכות ומנגינות שנכנסות ללב מיד. The Concept הפותח מספר על בחורה שלובשת ג׳ינס לאן שהיא הולכת, ומסתיים בסיום ארוך ויפה של גיטרות והרמוניות קוליות. Star Sign הוא שיר מהיר וסוחף, עם פזמון גדול, ו־What You Do to Me קצר, פשוט וממכר, בעיקר שורה אחת שחוזרת שוב ושוב. יש באלבום גם הומור, כמו בשמות השירים Alcoholiday ו־Metal Baby, ויש רגעים עצובים ושקטים כמו Guiding Star.''',
'''האלבום הפך את טינאייג׳ פנקלאב לאחת הלהקות האהובות של הפופ הגיטרות הבריטי, והשפיע על להקות רבות בשנים שאחריו. קורט קוביין ונואל גלאגר מאואזיס היו בין המעריצים שלהם, ושמם נשאר עד היום מילה נרדפת לפופ עם לב חם וגיטרות חזקות.''',
'''שמעו את The Concept עד הסוף, כולל הסיום הארוך, שבו הלהקה פשוט נהנית לנגן. ואחר כך שמעו את #1 Record של ביג סטאר (אלבום 242), וגלו מאיפה הם קיבלו את הקסם.''',
], [
('The Concept', 'הפותח, שיר על בחורה בג׳ינס, עם סיום ארוך ויפה של גיטרות והרמוניות.'),
('Star Sign', 'שיר מהיר וסוחף, עם גיטרות מזמזמות ופזמון ענק שמתאים לשירה בקולי קולות.'),
('What You Do to Me', 'שיר קצר, פשוט וממכר, בעיקר שורה אחת שחוזרת עד שהיא נתקעת בראש.'),
])

add(706, [
'''בסוף שנות השמונים מטאליקה היו להקת המטאל החשובה בעולם, עם אלבומים ארוכים, מהירים ומסובכים כמו Master of Puppets (אלבום 567) ו־...And Justice for All (אלבום 624). לאלבום החמישי, שיצא ב־1991 בלי שם ועם עטיפה שחורה כמעט לגמרי, הם רצו משהו אחר: שירים קצרים, פשוטים וכבדים יותר. הם בחרו במפיק בוב רוק, שעבד קודם עם להקות רוק פופולריות, והעבודה איתו הייתה ארוכה ומתוחה. בגלל העטיפה כולם קוראים לו עד היום "האלבום השחור".''',
'''הסאונד ענק, נקי ועמוק: תופים כבדים, גיטרות עבות והבס של ג׳ייסון ניוסטד, שסוף סוף שומעים אותו היטב. הקצבים איטיים יותר, והשירים בנויים סביב ריפים פשוטים ובלתי נשכחים. Enter Sandman הפותח, עם הריף המפורסם שלו, מספר על סיוטים של ילד לפני השינה. Sad but True כבד ואיטי כמו קיר, ו־Wherever I May Roam מביא צליל מזרחי של סיטאר לשיר על חיים בדרכים. The Unforgiven משלב גיטרות אקוסטיות ופזמון כבד, ו־Nothing Else Matters היא בלדה אישית ורכה, שג׳יימס הטפילד כתב על בדידות בדרכים, עם תזמורת כלי מיתר שעיבד מייקל קיימן.''',
'''האלבום הגיע למקום הראשון בארצות הברית ובבריטניה, ונמכר בעשרות מיליוני עותקים בעולם, אחד האלבומים הנמכרים בכל הזמנים. חלק מהמעריצים הוותיקים כעסו על השינוי, אבל מטאליקה הפכה בזכותו מלהקת מטאל לאחת הלהקות הגדולות בעולם.''',
'''שמעו קודם את Battery מתוך Master of Puppets ומיד אחריו את Sad but True, ותשמעו כמה הלהקה האטה והכבידה בחמש שנים בלבד.''',
], [
('Enter Sandman', 'הפותח, עם אחד הריפים המפורסמים בעולם, שיר על סיוטים של ילד לפני השינה.'),
('Nothing Else Matters', 'בלדה רכה ואישית, גיטרה אקוסטית ותזמורת, שהפתיעה את כל מעריצי המטאל.'),
('Sad but True', 'שיר איטי וכבד כמו קיר, עם ריף עבה וקול מאיים של הטפילד.'),
])

add(707, [
'''פייבמנט נולדו בסטוקטון, עיירה חקלאית בקליפורניה, כפרויקט של שני חברים, סטיבן מלקמוס וסקוט קנברג, שהקליטו שירים בזול באולפן ביתי של מתופף מבוגר ותמהוני בשם גארי יאנג. Slanted and Enchanted, אלבום הבכורה שלהם, הוקלט ב־1991 ויצא ב־1992 בחברת התקליטים הקטנה מטאדור. עוד לפני שיצא, קלטות שלו כבר עברו מיד ליד בין מבקרים ומעריצים, והשמועה עליו התפשטה. הלהקה אהבה מאוד את הפול, להקת הפוסט־פאנק הבריטית של מארק אי. סמית׳ (אלבום 546), ושומעים את זה בכל שיר.''',
'''הצליל מחוספס ולא מלוטש: גיטרות צורמות ולא מכוונות עד הסוף, רעשים, תופים פשוטים, ומלקמוס ששר בקול עצל ומשועשע, לפעמים כמעט מדבר. אבל מתחת לרעש מסתתרות מנגינות פופ יפות במיוחד. Summer Babe הפותח הוא שיר אהבה מבולבל עם גיטרה ממכרת ופזמון שקשה לשכוח. Here הוא שיר איטי, עצוב ויפה, על מישהו שמרגיש שלא שייך לשום מקום. Trigger Cut שמח וקופצני, ו־In the Mouth a Desert ו־Conduit for Sale! רועשים ופרועים יותר, כמעט פאנק.''',
'''Slanted and Enchanted הפך לאחד האלבומים החשובים של האינדי רוק האמריקאי, והראה שאפשר להקליט תקליט נהדר בלי כסף ובלי אולפן גדול. המילים המוזרות, החצי־מצחיקות, והגישה הרגועה והאירונית של מלקמוס השפיעו על להקות רבות בשנים הבאות, והפכו את פייבמנט לאחד הסמלים של שנות התשעים.''',
'''אל תחפשו כאן צליל נקי. שמעו את Here בשקט, בשעת ערב, ושימו לב כמה רגש מסתתר מאחורי הקול האדיש. ואחר כך שמעו את This Nation's Saving Grace של הפול (אלבום 546), כדי לשמוע את ההשראה.''',
], [
('Summer Babe', 'הפותח, שיר אהבה מבולבל עם גיטרה ממכרת ופזמון פשוט שנשאר בראש.'),
('Here', 'שיר איטי, עצוב ויפה, על מישהו שמרגיש שאינו שייך לשום מקום.'),
('Trigger Cut', 'שיר שמח וקופצני, עם פזמון שמזמינים לשיר ומילים מוזרות ומצחיקות.'),
])

add(708, [
'''ריצ׳רד די. ג׳יימס גדל בקורנוול, בקצה הדרום־מערבי של אנגליה, והתחיל עוד כנער לבנות ולשנות סינתיסייזרים ומכונות תופים בעצמו. הוא הופיע כתקליטן במסיבות בקורנוול, והוציא מוזיקה בשמות רבים, והמפורסם בהם הוא אייפקס טווין. Selected Ambient Works 85–92 יצא ב־1992 בחברת תקליטים בלגית קטנה, ולפי השם הוא אוסף של קטעים שהקליט במשך כשבע שנים, חלקם, לפי עדותו, עוד כשהיה נער צעיר. רבים מהקטעים הוקלטו על קלטות ביתיות פשוטות, ושומעים את רחש הקלטת ברקע.''',
'''למרות השם "אמביינט", זו לא מוזיקה שקטה וחסרת קצב: ברוב הקטעים יש קצב תופים רך, בס עמוק ומנגינות פשוטות וחמות שחוזרות שוב ושוב, כמו מוזיקת טכנו שהאטה ונרגעה. Xtal הפותח מרחף ויפה, עם קול נשי בלי מילים שמרחף מעל קצב קל. Ageispolis מתנדנד ומהפנט, ו־Heliosphan מהיר וזוהר יותר. We Are the Music Makers משלב משפט מתוך הסרט הישן על וילי וונקה ומפעל השוקולד. בסוף האלבום יש קטעים איטיים ועמוקים כמו Actium ו־Hedphelym, שנשמעים כמו מים או חלל.''',
'''האלבום נחשב לאחד האלבומים החשובים של המוזיקה האלקטרונית, והוא שילב את הרכות של בריאן אינו עם הקצב של מועדוני הטכנו. מוזיקאים רבים, גם מחוץ לעולם האלקטרוני, מזכירים אותו כהשראה, ואייפקס טווין עצמו הפך לאחד היוצרים המסקרנים והמוזרים של התקופה.''',
'''זה אלבום טוב לעבודה, לנסיעה בלילה או לשכיבה בחושך. שמעו אותו לצד Ambient 1: Music for Airports של בריאן אינו (אלבום 424), ושימו לב למה שהקצב מוסיף.''',
], [
('Xtal', 'הפותח, קול נשי בלי מילים שמרחף מעל קצב רך, כמו בוקר מעונן ושקט.'),
('Ageispolis', 'קצב מתנדנד ומנגינה פשוטה שחוזרת שוב ושוב, מהפנט ונעים במיוחד.'),
('Heliosphan', 'קטע מהיר וזוהר יותר, טכנו רך עם מנגינה מנצנצת ובס עמוק.'),
])

add(709, [
'''ארסטד דבלופמנט קמו באטלנטה בסוף שנות השמונים, סביב הראפר ספיץ׳, שגדל במילווקי ובילה את הקיצים אצל סבתו בעיירה קטנה בטנסי. הם היו יותר משפחה או קומונה מאשר להקה: ראפרים, זמרות, רקדנית, תקליטן ואפילו "זקן רוחני", בבא אוג׳ה, שתפקידו היה לייעץ ולהיות נוכח. שם האלבום מתייחס, כך סיפרו, לזמן שלקח להם לקבל חוזה הקלטות, מהיום שהתחילו. הוא יצא ב־1992, בתקופה שבה ההיפ הופ האמריקאי נשלט בידי הגנגסטה ראפ, והם הציעו משהו אחר לגמרי.''',
'''המוזיקה חמה, שמחה ומלאת שמש: קצבי היפ הופ רכים, בלוז, גוספל, פאנק, גיטרות אקוסטיות ושירה של מקהלה. המילים מדברות על אמונה, על משפחה, על הדרום הכפרי, על שורשים אפריקאיים ועל אחריות של גברים צעירים לקהילה שלהם. Tennessee, הלהיט הראשון, נכתב אחרי מותם של סבתו ואחיו של ספיץ׳, והוא תפילה שקטה וכנה לכיוון ומשמעות. People Everyday מבוסס על Everyday People של סליי אנד דה פמילי סטון (אלבום 159), ומספר סיפור על מפגש מתוח בפארק. Mr. Wendal הוא שיר רך על כבוד לאדם חסר בית שחי ברחוב.''',
'''האלבום נמכר במיליוני עותקים, וזכה בשני פרסי גראמי, כולל פרס האמן החדש הטוב ביותר, הראשון שניתן לקבוצת ראפ. הוא הוכיח שהיפ הופ חיובי, רוחני ואופטימי יכול להצליח בגדול, והשפיע על אמנים רבים שבאו אחריו.''',
'''שמעו את Tennessee ושימו לב לפזמון השקט, שנשמע כמו שיר בכנסייה. ואחר כך שמעו את 3 Feet High and Rising של דה לה סול (אלבום 659), עוד היפ הופ צבעוני ושמח מאותן שנים.''',
], [
('Tennessee', 'הלהיט הראשון, תפילה שקטה וכנה שנכתבה אחרי מות הסבתא והאח של ספיץ׳.'),
('People Everyday', 'מבוסס על שיר של סליי סטון, וסיפור על מפגש מתוח ביום חם בפארק.'),
('Mr. Wendal', 'שיר רך ומרגש על כבוד לאדם חסר בית, עם פזמון שקל לשיר יחד.'),
])

add(711, [
'''אחרי שהסמית׳ס התפרקו ב־1987, מוריסי המשיך לבד, והתחיל טוב עם Viva Hate (אלבום 629). אבל בתחילת שנות התשעים נראה היה שהקריירה שלו נתקעה, והביקורות היו פושרות. ל־Your Arsenal, שיצא ב־1992, הוא הביא מפיק מפתיע: מיק רונסון, הגיטריסט של דייוויד בואי בתקופת זיגי סטארדסט (אלבום 266). הוא גם עבד עם להקה חדשה וצעירה, שבה ניגנו שני גיטריסטים, אלן ווייט ובוז בורר, שאהבו רוקבילי ורוקנרול של שנות החמישים.''',
'''הצליל של האלבום שונה מאוד מהסמית׳ס: במקום הגיטרות המנצנצות של ג׳וני מאר יש כאן גיטרות חזקות, מחוספסות וגלאמיות, קצב רוקבילי מהיר, ותחושה של להקה שמנגנת יחד בחדר. You're Gonna Need Someone on Your Side הפותח מהיר ורועש, ו־Glamorous Glue הוא רוק גלאם כבד וצועד. We Hate It When Our Friends Become Successful מצחיק ושנון, על הקנאה בחברים שמצליחים. ובתוך כל הרעש יש גם רגעים רכים ויפים: Seasick, Yet Still Docked הוא שיר בדידות ארוך ועצוב, ו־I Know It's Gonna Happen Someday הוא בלדה דרמטית ומרגשת, כמו שיר של בואי.''',
'''דייוויד בואי עצמו אהב את I Know It's Gonna Happen Someday, והקליט לו גרסה משלו כבר בשנה שאחרי. רבים רואים ב־Your Arsenal את אלבום הסולו הטוב של מוריסי. מיק רונסון נפטר פחות משנה אחרי צאת האלבום, וזו הייתה אחת העבודות האחרונות שלו.''',
'''שמעו את I Know It's Gonna Happen Someday, ואחריו את Rock 'n' Roll Suicide מתוך זיגי סטארדסט (אלבום 266), ותשמעו את המחווה. ואחר כך חזרו ל־The Queen Is Dead (אלבום 583), להשוואה עם הסמית׳ס.''',
], [
('I Know It\'s Gonna Happen Someday', 'בלדה דרמטית ומרגשת, מחווה לבואי, שהקליט אותה אחר כך בעצמו.'),
('We Hate It When Our Friends Become Successful', 'שיר שנון ומצחיק על הקנאה בחברים שמצליחים, בקצב רוקבילי מקפץ.'),
('Seasick, Yet Still Docked', 'שיר בדידות ארוך, איטי ועצוב, עם גיטרה אקוסטית ושירה מלאת כאב.'),
])

add(713, [
'''הלמונהדס קמו בבוסטון באמצע שנות השמונים כלהקת פאנק רועשת, ובמרכזם עמד אוון דנדו, זמר יפה תואר עם קול חם ועמוק. במשך השנים חבריה התחלפו, והלהקה הפכה בעיקר לכלי של דנדו. ל־It's a Shame About Ray, שיצא ב־1992, הוא הגיע אחרי טיול באוסטרליה, שם כתב חלק מהשירים עם חברו האוסטרלי טום מורגן. האלבום הוקלט בלוס אנג׳לס, ובבס ובקולות הרקע השתתפה הזמרת ג׳וליאנה הטפילד.''',
'''זה אלבום קצר מאוד, כחצי שעה בלבד, מלא בשירי פופ רוק קצרים, מתוקים ונוגים, עם גיטרות חמות, מנגינות פשוטות וקול רך ועצל. רוב השירים נגמרים תוך שתיים או שלוש דקות, עוד לפני שמתעייפים מהם. שיר הנושא הוא שיר נוגה ומסתורי על חבר בשם ריי, שקשה להבין מה בדיוק קרה לו. Confetti קופצני ושמח, עם פזמון מתוק, ו־Rudderless הוא שיר עצוב על חוסר כיוון בחיים. Alison's Starting to Happen מהיר ומלא אנרגיה, ובסוף יש גרסה רכה לשיר Frank Mills מתוך המחזמר "שיער".''',
'''האלבום הפך את הלמונהדס ללהקה מצליחה, ואת דנדו לאחד הפנים המוכרות של האינדי רוק האמריקאי של התקופה. אחרי ההצלחה הוסיפה חברת התקליטים להוצאות החדשות של האלבום את הגרסה שלהם ל־Mrs. Robinson של סיימון וגרפונקל, שהפכה ללהיט, אבל היא לא הייתה חלק מהתקליט המקורי.''',
'''זה אלבום מושלם לנסיעה קצרה, או לבוקר שמש עצלן. שמעו אותו ברצף, ושימו לב כמה מהר הוא נגמר, וכמה מהר תרצו לשמוע אותו שוב.''',
], [
('It\'s a Shame About Ray', 'שיר הנושא, נוגה ומסתורי, על חבר בשם ריי שקשה להבין מה קרה לו.'),
('Confetti', 'שיר קופצני ושמח, עם גיטרות חמות ופזמון מתוק שנכנס ללב מיד.'),
('Rudderless', 'שיר עצוב ויפה על חוסר כיוון בחיים, בקול רך ועייף של דנדו.'),
])

add(714, [
'''רייג׳ אגיינסט דה מאשין קמו בלוס אנג׳לס ב־1991, וחיברו בין ארבעה אנשים שונים מאוד: הזמר והראפר זאק דה לה רושה, שבא מסצנת ההארדקור, הגיטריסט טום מורלו, בוגר הרווארד שלמד מדע המדינה, הבסיסט טים קומרפורד והמתופף בראד וילק. מההתחלה הם היו להקה פוליטית מאוד, שרצתה להשתמש ברוק כדי לדבר על עוול, על גזענות, על שלטון ועל מחאה. אלבום הבכורה שלהם, שנושא את שם הלהקה, יצא ב־1992.''',
'''המוזיקה היא שילוב כבד ומתפוצץ של מטאל, פאנק והיפ הופ: ריפים ענקיים ופשוטים, בס עמוק, תופים חזקים, ודה לה רושה שמתחיל בראפ שקט ומאיים ומסיים בצעקות. טום מורלו מוציא מהגיטרה צלילים מוזרים שנשמעים כמו סקרצ׳ים של תקליטן, סירנות ומכונות, ובחוברת האלבום נכתב בגאווה שלא השתמשו בדגימות, בקלידים או בסינתיסייזרים. Killing in the Name הוא שיר מחאה זועם נגד אלימות משטרתית וגזענות, שנבנה לאט לשיא מתפוצץ. Bombtrack הפותח מתחיל בבס שקט ומתפרץ, ו־Know Your Enemy ו־Wake Up כבדים ומלאי גרוב.''',
'''האלבום הפך את הלהקה לאחת החשובות של שנות התשעים, והשפיע על להקות רבות שחיברו בין רוק להיפ הופ. Killing in the Name חזר למודעות בשנת 2009, כשקמפיין של מאזינים בבריטניה הפך אותו לשיר מספר אחת בחג המולד, נגד שיר של תוכנית ריאליטי.''',
'''שמעו את Killing in the Name עד הסוף, ושימו לב איך השיר נבנה לאט ומתפוצץ בדקה האחרונה. ואחר כך שמעו את It Takes a Nation of Millions של פבליק אנמי (אלבום 634), השראה גדולה ללהקה.''',
], [
('Killing in the Name', 'שיר מחאה זועם, ריף ענק וסיום מתפוצץ, אחד השירים הכועסים בתולדות הרוק.'),
('Bombtrack', 'הפותח, בס שקט ומאיים שמתפרץ לריף כבד ולשירה צועקת ומלאת זעם.'),
('Wake Up', 'שיר כבד וגרובי על פוליטיקה והיסטוריה, עם ריף שמזכיר את לד זפלין.'),
])

add(715, [
'''הדיספוזבל הירוז אוף היפהופריסי היו צמד מסן פרנסיסקו: המשורר והראפר מייקל פרנטי, גבר גבוה עם קול עמוק ושקט, והמוזיקאי רונו טסה, שניגן בכלי הקשה מתכתיים ובקצבים. לפני כן ניגנו שניהם בלהקה ניסיונית ופוליטית בשם הביטניגס. Hypocrisy Is the Greatest Luxury, האלבום היחיד שלהם, יצא ב־1992, והוא אחד מאלבומי ההיפ הופ הפוליטיים והחכמים של התקופה. השם שלו פירושו "צביעות היא המותרות הגדולים ביותר".''',
'''המוזיקה מחברת היפ הופ עם רוק תעשייתי, ג׳אז ורעש: קצבים כבדים, צלילים של מתכת, דגימות של חדשות ושל נאומים, ומעל הכל הקול הרגוע של פרנטי, שמדבר יותר משהוא צועק. המילים עוסקות בגזענות, בתקשורת, במלחמה, בהומופוביה, בעוני ובשאלות של זהות. Television, the Drug of the Nation הוא שיר חכם וחד על ההשפעה של הטלוויזיה על החברה, ו־Language of Violence מספר סיפור על בריונות ועל אלימות שחוזרת בחזרה אל מי שהתחיל בה. Famous and Dandy עוסק בדימויים של אפרו־אמריקאים בתרבות, ויש גם גרסה חדשה ל־California Über Alles של הדד קנדיז (אלבום 457), עם מילים מעודכנות.''',
'''האלבום לא נמכר בכמויות גדולות, אבל זכה לשבחים רבים מצד מבקרים, והלהקה אפילו יצאה למסע הופעות עם U2 בתקופת Achtung Baby (אלבום 701). אחרי שהצמד התפרק, מייקל פרנטי הקים את להקת ספירהד, והמשיך לשלב מוזיקה עם מחאה.''',
'''הקשיבו כאן למילים. שמעו את Television, the Drug of the Nation לצד Fear of a Black Planet של פבליק אנמי (אלבום 679), ושימו לב לדרך השקטה והמדודה של פרנטי.''',
], [
('Television, the Drug of the Nation', 'שיר חכם וחד על הטלוויזיה כסם של אומה שלמה, בקול עמוק ושקט.'),
('Language of Violence', 'סיפור קשה על בריונות ועל אלימות שחוזרת בסוף אל מי שהתחיל בה.'),
('California Über Alles', 'גרסה חדשה ומעודכנת לשיר הפאנק של הדד קנדיז, בקצב כבד ומאיים.'),
])

add(716, [
'''קיי. די. לאנג גדלה בעיירה קטנה במחוז אלברטה בקנדה, והתפרסמה בשנות השמונים כזמרת קאנטרי שובבה ופרועה, עם קול ענק ותספורת קצרה, שהעריצה את פטסי קליין. אבל בתחילת שנות התשעים היא רצתה לצאת מעולם הקאנטרי. Ingénue, שיצא ב־1992, נכתב יחד עם המוזיקאי בן מינק, והוא אוסף של שירי אהבה רכים ועצובים על אהבה נכזבת, על תשוקה ועל געגוע למישהי שאי אפשר להשיג. באותה שנה היא גם סיפרה בפומבי על היותה לסבית, צעד אמיץ בשביל זמרת מפורסמת באותם ימים.''',
'''המוזיקה איטית, חמה ועשירה: כלי מיתר, אקורדיון, ויברפון, גיטרות רכות וכלי הקשה עדינים, שיוצרים אווירה של מועדון לילה ישן. ובמרכז עומד הקול של לאנג, אחד היפים של התקופה: עמוק, צלול ומלא רגש, שיודע להיות שקט מאוד ואז להתרומם לגובה עצום. Constant Craving, הלהיט הגדול, הוא שיר על געגוע שלא נגמר, עם מנגינה מתנדנדת ופזמון שאי אפשר לשכוח. Save Me ו־The Mind of Love רכים ומלאי כאב, ו־Miss Chatelaine הוא ואלס שובב, עם אקורדיון ומילים מצחיקות.''',
'''Constant Craving זכה בפרס גראמי על הביצוע הקולי הנשי, והאלבום נמכר במיליוני עותקים. הוא הפך את לאנג לכוכבת עולמית, והוכיח שזמרת שהגיעה מהקאנטרי יכולה ליצור פופ עדין, בוגר ומרגש.''',
'''זה אלבום ללילה שקט עם כוס יין. שמעו את Constant Craving, ושימו לב לרגע שבו הקול שלה מתרומם בפזמון. ואחר כך נסו את Blue של ג׳וני מיטשל (אלבום 229), עוד אלבום של לב שבור.''',
], [
('Constant Craving', 'הלהיט, שיר על געגוע שלא נגמר, עם מנגינה מתנדנדת ופזמון שאי אפשר לשכוח.'),
('Miss Chatelaine', 'ואלס שובב עם אקורדיון וכלי מיתר, ומילים מצחיקות על אהבה שמשנה את כולה.'),
('Save Me', 'שיר רך ומלא כאב על אהבה שאי אפשר להשיג, בקול צלול ונפלא.'),
])

add(717, [
'''דוקטור דרה היה המפיק של N.W.A (אלבום 662), הלהקה שהביאה את ההיפ הופ של לוס אנג׳לס לכל העולם. בתחילת שנות התשעים הוא עזב אותם בסכסוך, והקים יחד עם שותפים חברת תקליטים חדשה, דת׳ רואו. The Chronic, אלבום הסולו הראשון שלו, יצא בסוף 1992, ובו הציג לעולם ראפר צעיר וכמעט לא מוכר מלונג ביץ׳, סנופ דוגי דוג, שמופיע כמעט בכל השירים. השם לקוח מכינוי לסוג של מריחואנה.''',
'''דרה המציא כאן צליל חדש, שנקרא ג׳י־פאנק: קצבים איטיים ונינוחים, בס עמוק וחם, ודגימות מתקליטי הפאנק של פרלמנט ופאנקדליק (אלבומים 360 ו־409), לצד כלים שנוגנו באולפן וצליל גבוה ומייבב של סינתיסייזר. המוזיקה נשמעת כמו נסיעה איטית במכונית פתוחה ביום חם בקליפורניה. Nuthin' but a "G" Thang הוא הלהיט הגדול, דואט קליל ובטוח בעצמו בין דרה לסנופ. Let Me Ride נינוח וחלק, עם מקהלה שמזכירה את פרלמנט, ו־Lil' Ghetto Boy איטי ונוגה יותר. המילים בוטות מאוד, מלאות שפה גסה, אלימות ורגעים לא נעימים.''',
'''The Chronic נמכר במיליוני עותקים, והצליל שלו שלט בהיפ הופ האמריקאי במשך שנים. הוא הפך את דרה לאחד המפיקים החשובים בעולם, ואת סנופ לכוכב ענק. Let Me Ride זכה בפרס גראמי. דרה המשיך להפיק ולגלות אמנים רבים, ביניהם אמינם ו־50 סנט, וגם עשה הון גדול מעסקי האוזניות.''',
'''שמעו את Nuthin' but a "G" Thang ואחריו את One Nation Under a Groove של פאנקדליק (אלבום 409), ותשמעו איך פאנק של שנות השבעים הפך לבסיס של היפ הופ של שנות התשעים.''',
], [
('Nuthin\' but a "G" Thang', 'הלהיט, דואט קליל ובטוח בעצמו בין דרה לסנופ, מעל קצב איטי וחם.'),
('Let Me Ride', 'נינוח וחלק, עם מקהלה בסגנון פרלמנט, זכה בפרס גראמי לביצוע ראפ.'),
('Lil\' Ghetto Boy', 'שיר איטי ונוגה יותר, עם מנגינה רכה וסיפור עצוב על חיי השכונה.'),
])

add(718, [
'''בתחילת שנות התשעים R.E.M. מאתנס שבג׳ורג׳יה הפכו לאחת הלהקות הגדולות בעולם, אחרי ההצלחה של Losing My Religion מתוך Out of Time. מצופים היה שיוציאו אלבום שמח ומקפץ, אבל Automatic for the People, שיצא ב־1992, הוא אלבום שקט, איטי ועצוב, שעוסק במוות, בזיכרון, בהתבגרות ובאובדן. השם לקוח מהסיסמה של מסעדה קטנה באתנס, ועל עיבודי כלי המיתר בכמה מהשירים עבד ג׳ון פול ג׳ונס, הבסיסט של לד זפלין.''',
'''הצליל רך ועמוק: גיטרות אקוסטיות, מנדולינה, פסנתר, אקורדיון ותזמורת כלי מיתר, ומייקל סטייפ ששר בקול נמוך, חם וברור מתמיד. Drive הפותח איטי ומאיים, ו־Everybody Hurts הוא שיר פשוט ומנחם לכל מי שמרגיש שהוא לבד, שנכתב במיוחד כדי שגם צעירים יבינו אותו. Man on the Moon הוא שיר מצחיק ונוגה על הקומיקאי אנדי קאופמן, ועל השאלה אם באמת הגענו לירח. Nightswimming, עם הפסנתר וכלי המיתר, הוא זיכרון יפה ועצוב של שחייה בלילה עם חברים בגיל צעיר. The Sidewinder Sleeps Tonite הוא רגע של שמחה קטנה באמצע.''',
'''האלבום נמכר במיליוני עותקים, למרות שהלהקה לא יצאה איתו לסיבוב הופעות, ורבים רואים בו את האלבום הטוב ביותר של R.E.M. השירים Everybody Hurts ו־Nightswimming הפכו לאחד הרגעים היפים והאהובים של המוזיקה של שנות התשעים.''',
'''שמעו את האלבום בערב, ברצף ובשקט. ואחר כך חזרו ל־Murmur (אלבום 517), ותשמעו את אותה להקה עשר שנים קודם, צעירה, מסתורית ומהירה.''',
], [
('Everybody Hurts', 'שיר פשוט ומנחם לכל מי שמרגיש לבד, עם כלי מיתר וקול חם.'),
('Nightswimming', 'פסנתר וכלי מיתר, וזיכרון יפה ועצוב של שחייה בלילה עם חברים.'),
('Man on the Moon', 'שיר מצחיק ונוגה על הקומיקאי אנדי קאופמן, ועל ספק ואמונה.'),
])

add(719, [
'''הפארסייד היו ארבעה חברים מדרום לוס אנג׳לס: אימאני, בוטי בראון, סלימקיד3 ופאטליפ, שהתחילו את דרכם כרקדנים, לפני שעברו לראפ. בזמן שרוב ההיפ הופ של לוס אנג׳לס עסק בכנופיות, ברחובות ובאלימות, הם הציגו צד אחר לגמרי של העיר: מצחיק, מבולבל, ילדותי לפעמים, ומלא ספקות של בחורים צעירים. Bizarre Ride II the Pharcyde, אלבום הבכורה שלהם, יצא ב־1992, והופק על ידי המפיק הצעיר ג׳יי סוויפט, שבנה להם קצבים מלאים בג׳אז.''',
'''הקצבים חמים ומקפצים, מלאים בדגימות של ג׳אז, סול ופאנק ישנים, והארבעה מחליפים ביניהם את המיקרופון במהירות, עם קולות מצחיקים, צחוקים, שירה מזויפת בכוונה ובדיחות פנימיות. Passin' Me By הוא השיר המפורסם: שיר רך ונוגה על אהבה נכזבת, שבו כל אחד מהם מספר על בחורה שלא שמה לב אליו, מעל קצב איטי וחלומי. Ya Mama הוא תחרות מצחיקה של עלבונות על אמהות, ו־Otha Fish הוא שיר רגוע על פרידה ועל הניסיון להמשיך הלאה. Soul Flower שמח ומקפץ, ו־Officer מספר בהומור על בעיות עם שוטרים.''',
'''האלבום לא נמכר בכמויות גדולות בזמנו, אבל עם השנים הפך לאחד האלבומים האהובים של ההיפ הופ האלטרנטיבי של החוף המערבי. הוא השפיע על ראפרים רבים, שלמדו ממנו שמותר להיות מצחיק, חלש ופגיע גם בהיפ הופ.''',
'''שמעו את Passin' Me By בשקט, ושימו לב איך כל אחד מהארבעה מספר את הסיפור שלו. ואחר כך שמעו את The Low End Theory של א טרייב קולד קווסט (אלבום 696), עוד היפ הופ חם עם ג׳אז מאותה שנה.''',
], [
('Passin\' Me By', 'שיר רך ונוגה על אהבה נכזבת, ארבעה סיפורים קטנים מעל קצב חלומי.'),
('Ya Mama', 'תחרות מצחיקה ומשתוללת של עלבונות על אמהות, עם צחוקים וקולות משונים.'),
('Otha Fish', 'שיר רגוע ונינוח על פרידה ועל הניסיון להמשיך הלאה, מעל קצב חם.'),
])

add(720, [
'''ג׳ייסון פירס, המכונה ג׳יי ספייסמן, היה אחד משני המנהיגים של ספייסמן 3 (אלבום 641), הלהקה הבריטית שניגנה רוק פסיכדלי איטי, רועש ומהפנט. כשהלהקה התפרקה בתחילת שנות התשעים, אחרי ויכוחים קשים, פירס הקים להקה חדשה בשם ספיריצ׳ואלייזד, עם חלק מחברי הלהקה הקודמת ועם הקלידנית קייט ראדלי. Lazer Guided Melodies, אלבום הבכורה שלהם, יצא ב־1992, אחרי שנתיים של עבודה איטית וזהירה באולפן, והוא היה גדול ושאפתני הרבה יותר מכל מה שספייסמן 3 עשו.''',
'''האלבום בנוי כמו יצירה אחת ארוכה, מחולקת לארבעה חלקים, שבהם השירים זורמים זה לתוך זה בלי הפסקה. הצליל רך, מרחף וחלומי: גיטרות מהדהדות, עוגב, כלי נשיפה, כלי מיתר ושכבות של קולות, ופירס ששר בקול שקט ועייף על אהבה, על געגוע ועל בדידות. You Know It's True הפותח מתחיל בעדינות ונפתח לאט, ו־Run הוא שיר קצבי ורוקיסטי יותר, עם גיטרה מהפנטת. Smiles ו־Symphony Space רחבים ומרחפים, ו־Shine a Light, אחד השירים היפים באלבום, נשמע כמו תפילה שקטה בכנסייה ריקה.''',
'''Lazer Guided Melodies פתח את דרכה של ספיריצ׳ואלייזד, שהפכה לאחת הלהקות החשובות של הרוק הבריטי של שנות התשעים, עם אלבומים גדולים ומרשימים עוד יותר. פירס המשיך לחבר בין רוק, גוספל, ג׳אז ומוזיקה קלאסית, וחיפש תמיד את הצליל השלם והמרחף ביותר.''',
'''זה אלבום להאזנה באוזניות, בחושך ובשקט, מההתחלה ועד הסוף. שמעו אותו אחרי Playing with Fire של ספייסמן 3 (אלבום 641), ושימו לב כמה הצליל של פירס התרחב.''',
], [
('Shine a Light', 'שיר רך ויפה, כמו תפילה שקטה בכנסייה ריקה, עם עוגב וקולות מרחפים.'),
('Run', 'שיר קצבי ורוקיסטי יותר, עם גיטרה מהפנטת וקצב שמתגלגל בלי הפסקה.'),
('You Know It\'s True', 'הפותח, מתחיל בעדינות ונפתח לאט לאט לצליל רחב ומרחף.'),
])

add(721, [
'''בוב מולד היה הגיטריסט, הזמר וכותב השירים של הוסקר דו (אלבום 595), להקת הפאנק של מינסוטה שהשפיעה על כל הרוק האלטרנטיבי האמריקאי. אחרי שהלהקה התפרקה ב־1988 הוא הוציא שני אלבומי סולו שקטים וכבדים יחסית, ואז, ב־1992, הקים להקה חדשה בשם שוגר, עם הבסיסט דייוויד בארב והמתופף מלקולם טרוויס. Copper Blue, האלבום הראשון שלהם, יצא באותה שנה, בדיוק כשהרוק האלטרנטיבי, שמולד עזר לבנות, הפך פתאום לפופולרי בכל העולם אחרי ההצלחה של נירוונה.''',
'''המוזיקה רועשת ומתוקה בבת אחת: גיטרות עבות ומזמזמות, קצב מהיר ותופים חזקים, ובתוכם מנגינות פופ גדולות ופזמונים שנכנסים לראש מההאזנה הראשונה. The Act We Act הפותח נבנה לאט לחומה של גיטרות, ו־A Good Idea קצבי ומאיים, עם בס שמזכיר את הפיקסיז, ומספר סיפור אפל ומפחיד. Helpless ו־Changes הם שירי פופ רוק מושלמים, מהירים ושמחים, ו־If I Can't Change Your Mind, עם גיטרה אקוסטית מנצנצת, הוא אחד השירים המתוקים והקליטים שמולד כתב אי פעם. Hoover Dam ארוך ושאפתני, עם עוגב, ו־The Slim כבד ועצוב.''',
'''האלבום זכה לשבחים רבים, במיוחד בבריטניה, שם השבועון המוזיקלי NME בחר בו לאלבום השנה של 1992, ומולד, שהיה כבר אז ותיק, מצא את עצמו פתאום מצליח יותר מאשר בכל השנים שלפני כן. רבים רואים בו אחד האלבומים הטובים של הרוק האלטרנטיבי של התקופה.''',
'''שמעו את If I Can't Change Your Mind ואחריו את Warehouse: Songs and Stories של הוסקר דו (אלבום 595), ותשמעו איך הכותב המוכשר הזה המשיך להפוך רעש למנגינות יפות.''',
], [
('If I Can\'t Change Your Mind', 'גיטרה אקוסטית מנצנצת ומנגינה מתוקה, אחד השירים הקליטים שמולד כתב אי פעם.'),
('Helpless', 'שיר פופ רוק מהיר ושמח, עם גיטרות מזמזמות ופזמון גדול שמזמין לשיר.'),
('The Act We Act', 'הפותח, נבנה לאט לחומה עבה של גיטרות ופורץ בבת אחת לפזמון.'),
])

add(722, [
'''בסוף שנות השמונים טום ווייטס כבר השאיר מאחוריו את הזמר הרך של הבארים, והפך לממציא של עולם מוזיקלי מוזר משלו, בסדרת אלבומים שהתחילה ב־Swordfishtrombones (אלבום 519) והמשיכה ב־Rain Dogs (אלבום 558). Bone Machine, שיצא ב־1992, הגיע אחרי הפסקה של כמה שנים, שבה עבד על הצגות ועל סרטים. הוא הוקלט בחדר אבן ריק במרתף של אולפן בצפון קליפורניה, ורוב השירים נכתבו יחד עם אשתו, קתלין ברנן, ששותפה לרוב היצירה שלו מאז.''',
'''הצליל גולמי, חשוף ומפחיד: תופים כבדים ופשוטים, כלי הקשה שנבנו מגרוטאות ופחים, גיטרות צורמות, בס עמוק, וקולו הצרוד של ווייטס, שלפעמים צועק ולפעמים לוחש. הרבה מהשירים עוסקים במוות, בזמן שעובר, באמונה ובפחד, אבל יש בהם גם הומור שחור וחום. The Earth Died Screaming הפותח הוא חזון אפוקליפטי עם תופים ענקיים. Dirt in the Ground הוא שיר איטי ועצוב על כך שכולנו נחזור בסוף לאדמה, ו־Who Are You מר וכועס. I Don't Wanna Grow Up הוא שיר מצחיק ופרוע על ילד שלא רוצה להתבגר, ו־That Feel, שכתב ושר יחד עם קית׳ ריצ׳רדס מהרולינג סטונס, סוגר את האלבום בחום.''',
'''Bone Machine זכה בפרס גראמי לאלבום המוזיקה האלטרנטיבית, ונחשב לאחת העבודות החשובות של ווייטס. הרמונס הקליטו אחר כך גרסה משלהם ל־I Don't Wanna Grow Up.''',
'''שמעו את האלבום בחושך, ושימו לב לכלי ההקשה המוזרים. ואחר כך חזרו ל־Nighthawks at the Diner (אלבום 338), ותשמעו כמה רחוק ווייטס הגיע מימיו כזמר של בארים.''',
], [
('I Don\'t Wanna Grow Up', 'שיר מצחיק ופרוע על ילד שלא רוצה להתבגר, עם תופים מקרקשים.'),
('Dirt in the Ground', 'שיר איטי ועצוב על כך שכולנו נחזור בסוף לאדמה, בקול צרוד ושבור.'),
('That Feel', 'הסוגר, שיר חם ועייף שכתב ושר יחד עם קית׳ ריצ׳רדס מהרולינג סטונס.'),
])

add(723, [
'''אחרי שנים של רוק ניסיוני ורועש בחברות תקליטים קטנות, סוניק יות׳ חתמו בחברה גדולה, והוציאו את Goo (אלבום 682). הם גם עזרו לנירוונה, להקה צעירה שהם אהבו, לחתום באותה חברה, וכשנירוונה הפכה לתופעה עולמית, נפתחה הדלת לכל הרוק האלטרנטיבי. ל־Dirty, שיצא ב־1992, הם בחרו בבוץ׳ ויג, המפיק של Nevermind (אלבום 685), כדי לנסות להגיע לקהל גדול יותר בלי לאבד את הרעש שלהם. העטיפה, עם בובת צמר מלוכלכת, היא עבודה של האמן מייק קלי.''',
'''הצליל של Dirty חזק, ישיר וכבד יותר מכל מה שעשו קודם: שירים קצרים יותר, גיטרות עבות ומלוכלכות, ופחות קטעי רעש ארוכים. שלושת הזמרים, ת׳רסטון מור, קים גורדון ולי רנאלדו, מחליפים ביניהם את המיקרופון. 100% הפותח, עם פזמון רועש וגיטרה צורמת, נכתב לזכרו של חבר שנהרג. Sugar Kane הוא אחד השירים הפופיים והיפים שלהם, עם מנגינה מתוקה ושקטים ארוכים, ו־Drunken Butterfly ו־Swimsuit Issue של קים גורדון חדים, כועסים ומצחיקים. ב־Youth Against Fascism מצטרף כגיטריסט אורח איאן מקקיי מפוגאזי (אלבום 657).''',
'''Dirty היה האלבום המצליח ביותר של סוניק יות׳ מבחינה מסחרית. הוא נשמע כמו תמונה של רוק אלטרנטיבי בשיא כוחו, בשנה שבה הוא הפך לחלק מהזרם המרכזי, והשפיע על להקות צעירות רבות.''',
'''שמעו את Sugar Kane ואחריו את Teen Age Riot מתוך Daydream Nation (אלבום 630), ותשמעו איך הרעש הניסיוני של הלהקה הפך לאט לפופ רועש ויפה.''',
], [
('Sugar Kane', 'אחד השירים הפופיים והיפים שלהם, מנגינה מתוקה, גיטרות מזמזמות ושקטים ארוכים.'),
('100%', 'הפותח, גיטרה צורמת ופזמון רועש, שיר שנכתב לזכרו של חבר קרוב.'),
('Youth Against Fascism', 'שיר מחאה רועש וכועס, עם איאן מקקיי מפוגאזי בגיטרה נוספת.'),
])

add(724, [
'''הסטריאו אם סיז קמו בלונדון באמצע שנות השמונים, סביב שני חברים, הראפר רוב בירץ׳, המכונה רוב בי, והמפיק ניק הלאם, המכונה דה הד. הם אהבו היפ הופ אמריקאי, פאנק וסול, וניסו לבנות גרסה בריטית משלהם, עם קצב רחוב חם ועם אווירה של מסיבה. עם הזמן הצטרפו אליהם המתופף אוון איף והזמרת קת׳ קופי, שקולה העשיר מוסיף נשמה לשירים. Connected, האלבום השלישי שלהם, יצא ב־1992, והיה הפריצה הגדולה שלהם.''',
'''המוזיקה מחברת היפ הופ, פאנק, סול ומוזיקת ריקודים: בס עבה וגמיש, תופים חיים, דגימות של תקליטים ישנים, מקהלות נשיות, והראפ המחוספס והנינוח של רוב בי. Connected, שיר הנושא, נבנה על דגימה מתוך שיר דיסקו של ג׳ימי בו הורן, והוא אחד השירים הקליטים של שנות התשעים, עם קצב שאי אפשר לעמוד מולו בלי לזוז. Step It Up שמח וקופצני, עם פזמון שקורא לכולם לרקוד, ו־Ground Level ו־Everything מביאים גרוב איטי ועמוק יותר. Fade Away ו־The End רגועים וחלומיים, ומראים צד שקט של הלהקה.''',
'''Connected נמכר בהצלחה רבה, במיוחד בבריטניה, ושיר הנושא ו־Step It Up הפכו ללהיטים במצעד הבריטי. הלהקה זכתה בפרסי הבריט כלהקה הבריטית הטובה ביותר, והאלבום הפך לאחד הסמלים של הקיץ הבריטי של תחילת שנות התשעים, שבו היפ הופ, רוק ומוזיקת מסיבות התערבבו יחד.''',
'''שמעו את Connected בווליום גבוה, ושימו לב לבס. ואחר כך שמעו את Blue Lines של מסיב אטאק (אלבום 703), צד אחר, איטי ואפל יותר, של אותו חיבור בריטי בין היפ הופ לסול.''',
], [
('Connected', 'שיר הנושא, דגימה של דיסקו ישן וקצב גמיש שאי אפשר לעמוד מולו בלי לזוז.'),
('Step It Up', 'שיר שמח וקופצני, עם פזמון שקורא לכולם לקום מהכיסא ולרקוד.'),
('Ground Level', 'גרוב איטי ועמוק, עם בס עבה, קולות נשיים וראפ נינוח ומחוספס.'),
])

add(725, [
'''מיניסטרי היא להקה משיקגו, שבראשה עומד אל יורגנסן, שהתחיל בתחילת שנות השמונים כזמר של פופ אלקטרוני מתוק, ושנא את התוצאה. בסוף העשור הוא הפך את הלהקה לאחת החלוצות של המטאל התעשייתי, סגנון שמחבר גיטרות מטאל כבדות עם מכונות, דגימות ורעש. האלבום שיצא ב־1992 נקרא באותיות יווניות שקשה לקרוא, ולכן כולם מכנים אותו Psalm 69. יחד עם הבסיסט פול בארקר, יורגנסן בנה אותו באולפן מתוך שכבות של גיטרות, קצבים אלקטרוניים ודגימות מסרטים ומחדשות.''',
'''הצליל קשה, מהיר ומכני: ריפים של מטאל שחוזרים שוב ושוב כמו מכונה, תופים אלקטרוניים מהירים, צעקות מעוותות ודגימות של נאומים. N.W.O. הפותח הוא שיר מחאה פוליטי, שבו חוזרות שוב ושוב מילים של נשיא ארצות הברית דאז, ג׳ורג׳ בוש, על "סדר עולמי חדש". Jesus Built My Hotrod הוא שיר משוגע ומצחיק, עם שירה מבולבלת ופרועה של גיבי היינס מלהקת הבאטהול סרפרס, וקצב מהיר כמו מרוץ מכוניות. Just One Fix כבד ואפל, ו־Scarecrow איטי, ארוך ומאיים.''',
'''האלבום הגיע למקום גבוה במצעד האמריקאי, והלהקה הופיעה באותה שנה בפסטיבל הנודד לולאפלוזה, מול קהל ענק. Psalm 69 נחשב לאחד האלבומים החשובים של המטאל התעשייתי, והשפיע על להקות רבות של מטאל ורוק תעשייתי בשנות התשעים.''',
'''זה אלבום קשה להאזנה, רועש ואגרסיבי. התחילו מ־Jesus Built My Hotrod, המצחיק והקל ביותר. ואחר כך שמעו את L'eau rouge של היאנג גודס (אלבום 644), עוד צד של רוק שפוגש מכונות.''',
], [
('Jesus Built My Hotrod', 'שיר משוגע ומצחיק, עם שירה פרועה של גיבי היינס וקצב של מרוץ מכוניות.'),
('N.W.O.', 'הפותח, שיר מחאה מכני ומהיר, עם דגימות של נאום על סדר עולמי חדש.'),
('Scarecrow', 'שיר איטי, ארוך וכבד, עם ריף מאיים שחוזר שוב ושוב כמו טקס אפל.'),
])

add(726, [
'''טורי איימוס גדלה במרילנד, בתם של כומר מתודיסטי ואם עם שורשים צ׳רוקיים. היא הייתה ילדת פלא בפסנתר, והתקבלה לקונסרבטוריון יוקרתי כבר בגיל חמש, אבל עזבה אותו כעבור כמה שנים, כי רצתה לנגן רוק ופופ ולא רק מוזיקה קלאסית. בשנות השמונים ניגנה בבארים בוושינגטון ובלוס אנג׳לס, וב־1988 הוציאה אלבום רוק עם להקה, שנכשל לגמרי. Little Earthquakes, שבו חזרה לפסנתר ולשירים אישיים, יצא בתחילת 1992, קודם כל בבריטניה, שבה עברה לגור כדי להתחיל מחדש.''',
'''במרכז האלבום עומדים הפסנתר והקול של איימוס, שיכול להיות שקט ושביר, ולפתע לצעוק ולהתפרץ. המילים אישיות מאוד ועוסקות באמונה, במיניות, במשפחה, בכעס ובכאב, בגילוי לב נדיר. Silent All These Years הוא שיר על אישה שמוצאת סוף סוף את הקול שלה, עם פסנתר קטן ומקסים וכלי מיתר. Crucify חזק וכועס, על אשמה ועל דת. Winter הוא שיר רך ומרגש על אביה ועל ההתבגרות. Precious Things מתפרץ בזעם, ו־China עדין ויפה. Me and a Gun הוא שיר אישי וקשה מאוד, שהיא שרה לבד בלי שום ליווי.''',
'''האלבום הפך את איימוס לכוכבת, ופתח את הדרך לגל של זמרות־כותבות בשנות התשעים, שכתבו על עצמן בכנות ובחופש. היא הפכה גם לפעילה למען נפגעות ונפגעי אלימות, והקימה ארגון סיוע.''',
'''שמעו את Winter בשקט, ושימו לב לפסנתר ולכלי המיתר. ואחר כך שמעו את Hounds of Love של קייט בוש (אלבום 556), אחת ההשראות הגדולות של איימוס.''',
], [
('Silent All These Years', 'שיר על אישה שמוצאת את הקול שלה, עם פסנתר קטן ומקסים וכלי מיתר.'),
('Winter', 'שיר רך ומרגש על אביה ועל ההתבגרות, עם פסנתר וכלי מיתר עדינים.'),
('Crucify', 'הפותח, חזק וכועס, על אשמה ועל דת, עם פזמון שמתפרץ בעוצמה.'),
])

add(727, [
'''אייס קיוב עזב את N.W.A (אלבום 662) בסוף שנות השמונים, והפך לאחד הראפרים החשובים בארצות הברית, עם AmeriKKKa's Most Wanted (אלבום 676). The Predator, האלבום השלישי שלו, יצא בסוף 1992, כמה חודשים אחרי המהומות הגדולות בלוס אנג׳לס, שפרצו אחרי זיכוי השוטרים שהיכו את רודני קינג. האלבום מלא בכעס על האירועים האלה, על היחס של המשטרה ושל התקשורת לשכונות השחורות, ועל הפער בין העשירים לעניים בעיר.''',
'''הקצבים כבדים, פאנקיים וחמים, עם דגימות של סול ופאנק ישנים, והראפ של קיוב חד, מהיר ומלא ביטחון. רוב השירים כועסים ובוטים, עם שפה קשה ורגעים לא נעימים, אבל באמצע האלבום יש שיר אחד שונה לגמרי, שהפך לאחד השירים האהובים בתולדות ההיפ הופ: It Was a Good Day. זה שיר רגוע ונינוח על יום אחד שבו הכל הולך טוב, בלי צרות ובלי אלימות, מעל דגימה רכה מתוך שיר של האחים איזלי. Check Yo Self, עם הצמד דאס אפקס, הוא אזהרה קצבית וחדה, ו־Wicked מהיר וכבד.''',
'''The Predator הגיע למקום הראשון במצעד האלבומים האמריקאי, הישג נדיר לאלבום היפ הופ באותם ימים. הוא נחשב לאחד האלבומים החשובים שנוצרו בעקבות המהומות, ואייס קיוב המשיך אחר כך לקריירה גדולה גם כשחקן, ככותב וכבמאי.''',
'''שמעו את It Was a Good Day, ושימו לב כמה רגיל ופשוט ה"יום הטוב" שהוא מתאר. ואחר כך שמעו את The Chronic של דוקטור דרה (אלבום 717), מאותה שנה ומאותה עיר.''',
], [
('It Was a Good Day', 'שיר רגוע ונינוח על יום אחד שבו הכל הולך טוב, אחד האהובים בהיפ הופ.'),
('Check Yo Self', 'אזהרה קצבית וחדה, עם הצמד דאס אפקס וקצב כבד ומקפץ.'),
('Wicked', 'שיר מהיר, כבד ורועש, עם ראפ חד וקצב שלא נותן לנשום.'),
])

add(728, [
'''פנטרה קמו בארלינגטון שבטקסס בתחילת שנות השמונים, כלהקת גלאם מטאל עם שיער ארוך ובגדים צבעוניים, שלא הצליחה במיוחד. בסוף העשור הם החליפו כיוון: הצטרף אליהם הזמר פיל אנסלמו, הצליל הפך כבד וקשוח, והם הפסיקו להתלבש כמו כוכבי רוק. האחים דימבאג דארל, גיטריסט מוכשר במיוחד, ווינני פול, המתופף, היו הלב של הלהקה, יחד עם הבסיסט רקס בראון. Vulgar Display of Power, שיצא ב־1992, הוא האלבום שבו מצאו לגמרי את הצליל שלהם.''',
'''הצליל של פנטרה נקרא גרוב מטאל: לא מהיר כמו המטאל של מטאליקה או סלייר, אלא איטי יותר, כבד ומקפץ, עם ריפים שמתקדמים כמו פטיש וקצב שגורם לראש לזוז מעצמו. הגיטרה של דימבאג חדה, עבה ומלאה בצלילים צורמים, וסולואים מבריקים, ואנסלמו צועק בכעס כמעט כל הזמן. Walk הוא השיר המפורסם, עם ריף איטי ומקפץ ופזמון קצר וכועס על כבוד, שנקרא לחזור אחריו. Mouth for War הפותח מהיר וזועם, ו־This Love מתחיל בשקט ובעצב ומתפוצץ בכעס. Hollow הסוגר איטי ועצוב יותר, ומסתיים בסערה.''',
'''האלבום הפך את פנטרה לאחת להקות המטאל החשובות של שנות התשעים, בתקופה שבה הגראנג׳ דחק את המטאל הצידה. הם השפיעו על דור שלם של להקות מטאל, ו־Walk הפך להמנון שמושמע עד היום במועדונים ובאצטדיונים.''',
'''שמעו את Walk ואחריו את Sad but True של מטאליקה (אלבום 706), שני ריפים איטיים וכבדים מאותה שנה, ושימו לב להבדלים בגרוב.''',
], [
('Walk', 'השיר המפורסם, ריף איטי ומקפץ ופזמון קצר וכועס על כבוד, שכולם צועקים.'),
('Mouth for War', 'הפותח, ריף מהיר וזועם וקצב שלא נותן לרגע של מנוחה.'),
('This Love', 'מתחיל בשקט ובעצב בגיטרה נקייה, ומתפוצץ בבת אחת לכעס כבד.'),
])

add(729, [
'''אליס אין צ׳יינס קמו בסיאטל בסוף שנות השמונים, ושילבו בין הכבדות של המטאל לבין העצב של הגראנג׳. בלב הלהקה עמדו שני אנשים: הזמר ליין סטיילי, עם קול עמוק, חזק ומיוסר, והגיטריסט ג׳רי קנטרל, שכתב את רוב המוזיקה ושר איתו בהרמוניות מוזרות וכהות, שהפכו לסימן ההיכר שלהם. Dirt, האלבום השני שלהם, יצא ב־1992, בשנה שבה הגראנג׳ של סיאטל כבש את העולם.''',
'''Dirt הוא אלבום כבד, אפל ועצוב מאוד. הגיטרות עבות ואיטיות, הקצב כבד ומתגלגל, ושני הקולות שזורים זה בזה בהרמוניות שנשמעות כמו קינה. רבים מהשירים עוסקים בהתמכרות, בבדידות ובמוות, בכנות קשה ובלי יופי מזויף. Them Bones הפותח קצר ומהיר, עם ריף מוזר ושאגות. Rooster, שכתב קנטרל, מספר על אביו, שלחם במלחמת וייטנאם, והוא שיר איטי ונוגה שמתפוצץ בפזמון. Down in a Hole הוא שיר עצוב ויפה על ייאוש ועל אהבה, ו־Would?, הסוגר, נכתב לזכרו של אנדרו ווד, זמר מסיאטל שמת צעיר.''',
'''Dirt נמכר במיליוני עותקים, ונחשב לאחד האלבומים החשובים של הגראנג׳ ושל המטאל של שנות התשעים. ליין סטיילי נאבק בהתמכרות במשך שנים, ומת ב־2002, והלהקה חזרה מאוחר יותר עם זמר חדש.''',
'''זה אלבום קשה ועצוב, אבל יפה. שמעו את Rooster, ושימו לב להרמוניות של שני הזמרים. ואחר כך שמעו את Ten של פרל ג׳אם (אלבום 697), עוד אלבום גדול מאותה סצנה של סיאטל.''',
], [
('Rooster', 'שיר איטי ונוגה שמתפוצץ בפזמון, על אביו של קנטרל שלחם בווייטנאם.'),
('Would?', 'הסוגר, בס עמוק ופזמון ענק, נכתב לזכרו של זמר מסיאטל שמת צעיר.'),
('Down in a Hole', 'שיר עצוב ויפה על ייאוש ועל אהבה, עם הרמוניות כהות ועמוקות.'),
])

add(730, [
'''ניק קייב הוא זמר וכותב אוסטרלי, שהתחיל את דרכו בלהקת הפוסט־פאנק הפרועה הבירת׳דיי פארטי, ובשנות השמונים הקים את הבד סידס, להקה שבה ניגן גם בארי אדמסון (אלבום 653). בתחילת שנות התשעים הוא גר בסאו פאולו שבברזיל, נשוי ואב לילד, ונראה רגוע יותר מאשר בשנים הקודמות. ל־Henry's Dream, שיצא ב־1992, הוא בחר במפיק דייוויד בריגס, שהפיק שנים רבות את ניל יאנג, כולל Everybody Knows This Is Nowhere (אלבום 135). קייב עצמו לא אהב את הצליל הסופי, שנשמע לו חלק מדי.''',
'''השירים כתובים כמו סיפורים ובלדות עתיקות: רוצחים, נוודים, קדושים ונשים אבודות, בעולם אפל ואלים ומלא תמונות תנ״כיות. הלהקה מנגנת בעוצמה, עם גיטרות אקוסטיות שנפרטות בחוזקה, פסנתר, עוגב ותופים כבדים, וקייב שר בקול עמוק, דרמטי ומאיים, כמו מטיף. Papa Won't Leave You, Henry הפותח הוא סיפור ארוך ומבהיל, מעין שיר ערש מוזר שבו אב מבטיח לבנו שלא יעזוב. Straight to You הוא שיר אהבה גדול ומרגש, עם עוגב ופזמון רחב. Brother, My Cup Is Empty מר ומצחיק, ו־Christina the Astonishing מספר בעדינות על קדושה מימי הביניים. Jack the Ripper הסוגר רועש וזועם.''',
'''Henry's Dream נחשב לאחד האלבומים הטובים של קייב בתקופה ההיא, וגשר בין הרעש של שנות השמונים לבלדות השקטות והגדולות שכתב בשנים הבאות. כמה מהשירים זכו לגרסאות חיות חזקות יותר, באלבום הופעה שיצא שנה אחר כך.''',
'''שמעו את Straight to You, ואחריו את Papa Won't Leave You, Henry, ותשמעו את שני הצדדים של קייב: הרומנטי והמבהיל. ואחר כך נסו את Rain Dogs של טום ווייטס (אלבום 558), ממשפחה מוזיקלית קרובה.''',
], [
('Straight to You', 'שיר אהבה גדול ומרגש, עם עוגב, פסנתר ופזמון רחב שעולה ועולה.'),
('Papa Won\'t Leave You, Henry', 'הפותח, סיפור ארוך ומבהיל על אב ובן, עם גיטרות אקוסטיות סוערות.'),
('Christina the Astonishing', 'שיר שקט ומוזר על קדושה מימי הביניים, עם ליווי עדין ומינימלי.'),
])

add(732, [
'''פולי ג׳ין הארווי גדלה בחווה בכפר קטן בדורסט, בדרום־מערב אנגליה, להורים שאהבו בלוז ורוק, ובבית שבו התנגנו כל הזמן תקליטים. היא ניגנה סקסופון וגיטרה בכמה להקות מקומיות, ובתחילת שנות התשעים הקימה שלישייה משלה, עם המתופף רוב אליס והבסיסט סטיב וון, שנקראה פשוט פי. ג׳יי. הארווי. Dry, אלבום הבכורה שלהם, יצא ב־1992 בחברת תקליטים קטנה, כשהיא הייתה בת עשרים ושתיים בלבד, והוא עורר מיד התלהבות בקרב מבקרים ומוזיקאים.''',
'''הצליל חשוף, יבש וקשוח, כמו השם: גיטרה חדה ומחוספסת, בס חם, תופים פשוטים, וקול של הארווי שעובר מלחישה לצעקה, משירה שקטה לנהמה. המילים עוסקות בגוף, באהבה, במיניות, בתשוקה ובכעס, מנקודת מבט של אישה צעירה, בחדות ובהומור שלא נשמעו כך קודם. Sheela-Na-Gig, על פסל עתיק ומוזר של אישה, מצחיק ונוקב, עם פזמון שקשה לשכוח. Dress הוא סיפור על בחורה שמנסה להתאים את עצמה לשמלה ולציפיות, ו־Oh My Lover הפותח איטי, כבד וחושני. Victory ו־Happy and Bleeding מראים עד כמה הלהקה יודעת לעבור משקט לרעש.''',
'''האלבום הפך את הארווי לאחד הקולות החשובים והמסקרנים של הרוק בשנות התשעים. קורט קוביין כתב ברשימות שלו שזה אחד האלבומים האהובים עליו, והיא המשיכה ליצור במשך עשורים, ושינתה את הסגנון שלה כמעט בכל אלבום.''',
'''שמעו את Sheela-Na-Gig ואת Dress, ושימו לב לקול שלה. ואחר כך שמעו את Horses של פטי סמית׳ (אלבום 342), עוד אמנית צעירה שהגיעה לרוק עם קול בלתי מתפשר.''',
], [
('Sheela-Na-Gig', 'שיר מצחיק ונוקב על פסל עתיק של אישה, עם פזמון חד שאי אפשר לשכוח.'),
('Dress', 'סיפור על בחורה שמנסה להתאים את עצמה לשמלה ולציפיות של אחרים.'),
('Oh My Lover', 'הפותח, איטי, כבד וחושני, עם בס עמוק וקול שעולה לאט לאט.'),
])

add(733, [
'''סוויד קמו בלונדון בתחילת שנות התשעים, סביב הזמר ברט אנדרסון והגיטריסט הצעיר והמוכשר ברנרד באטלר, יחד עם הבסיסט מאט אוסמן והמתופף סיימון גילברט. הם אהבו את דייוויד בואי, את הסמית׳ס ואת הגלאם רוק של שנות השבעים, ורצו להחזיר לרוק הבריטי את הדרמה, את הסטייל ואת הסקס. עוד לפני שהוציאו סינגל אחד, הם כבר הופיעו על שער של שבועון מוזיקה בריטי, שכינה אותם הלהקה החדשה הטובה בבריטניה. אלבום הבכורה שלהם, שנושא את שמם, יצא ב־1993, והיה אחד מאלבומי הבכורה שנמכרו הכי מהר בבריטניה באותן שנים.''',
'''הצליל דרמטי, סקסי ומלא תיאטרון: הגיטרות של באטלר מתפתלות, מנצנצות ומתפוצצות, ואנדרסון שר בקול גבוה, מתנגן ומוגזם, על חיים בפרברים האפורים של לונדון, על אהבה, על תשוקה, על סמים ועל צעירים שחולמים על משהו אחר. Animal Nitrate הוא הלהיט הגדול, שיר קצבי וסוחף עם ריף גיטרה מפורסם. The Drowners, הסינגל הראשון, איטי, חושני ומלא גלאם, ו־Metal Mickey רועש וקופצני. So Young הפותח מלא אנרגיה ותקווה, ו־Sleeping Pills ו־The Next Life הם בלדות יפות ועצובות, עם פסנתר וקול שבור.''',
'''האלבום זכה בפרס מרקורי של 1993, ורבים רואים בו את נקודת ההתחלה של הבריטפופ, הגל הגדול של הלהקות הבריטיות של אמצע שנות התשעים. באטלר עזב את הלהקה כבר באלבום הבא, אחרי מתחים קשים עם אנדרסון.''',
'''שמעו את Animal Nitrate ואחריו את The Rise and Fall of Ziggy Stardust של בואי (אלבום 266), ותשמעו את ההשראה. ואחר כך שמעו את The Queen Is Dead של הסמית׳ס (אלבום 583).''',
], [
('Animal Nitrate', 'הלהיט הגדול, שיר קצבי וסוחף עם ריף גיטרה מפורסם וקול מוגזם ונהדר.'),
('The Drowners', 'הסינגל הראשון, איטי, חושני ומלא גלאם, עם גיטרה מתפתלת ומפתה.'),
('The Next Life', 'הסוגר, בלדה יפה ועצובה עם פסנתר וקול שבור, על חלום לברוח יחד.'),
])

add(735, [
'''הסמאשינג פאמפקינס קמו בשיקגו בסוף שנות השמונים, סביב בילי קורגן, זמר, גיטריסט וכותב שירים שאפתני מאוד, יחד עם הגיטריסט ג׳יימס איהה, הבסיסטית דארסי רצקי והמתופף ג׳ימי צ׳מברלין. Siamese Dream, האלבום השני שלהם, הוקלט ב־1992 עם המפיק בוץ׳ ויג, שהפיק קודם את Nevermind של נירוונה (אלבום 685). העבודה עליו הייתה קשה מאוד: הלהקה נסעה להקליט בעיירה בג׳ורג׳יה כדי להתרחק מהסחות הדעת, היו מתחים גדולים בין החברים, וקורגן, שסבל מדיכאון, ניגן בעצמו את רוב הגיטרות והבס.''',
'''הצליל עצום, עבה ומבריק: עשרות שכבות של גיטרות שמונחות זו על זו כמו קיר, תופים מהירים ווירטואוזיים של צ׳מברלין, וקולו הגבוה והמתלונן של קורגן. אבל מתחת לרעש יש מנגינות יפות, רכות וחלומיות, ולפעמים גם כלי מיתר ופעמונים. Cherub Rock הפותח נבנה מתופים שקטים לחומה של גיטרות. Today נשמע כמו שיר שמח וקיצי, אבל מאחוריו עומדים רגשות קשים של קורגן. Disarm הוא בלדה עם כלי מיתר ופעמונים על ילדות כואבת, ו־Mayonaise הוא שיר אהבה איטי ויפה. Silverfuck ארוך ופרוע, וחוזר ומתפוצץ.''',
'''Siamese Dream נמכר במיליוני עותקים, והפך את הסמאשינג פאמפקינס לאחת הלהקות הגדולות של שנות התשעים. הוא נחשב לאחד האלבומים היפים והשאפתניים של הרוק האלטרנטיבי, שבו רעש גדול הפך למשהו מתוק וחלומי.''',
'''שמעו את Today ואת Disarm, ושימו לב לניגוד בין הקול השמח לבין המילים. ואחר כך שמעו את Isn't Anything של מיי בלאדי ולנטיין (אלבום 622), עוד אלבום של גיטרות בשכבות.''',
], [
('Today', 'נשמע כמו שיר קיצי ושמח, אבל מאחורי המנגינה המתוקה מסתתרים רגשות קשים.'),
('Disarm', 'בלדה עם כלי מיתר ופעמונים על ילדות כואבת, אחד השירים היפים שלהם.'),
('Cherub Rock', 'הפותח, נבנה מתופים שקטים לחומה ענקית של גיטרות וקול מתלונן.'),
])

add(734, [
'''פול ולר היה המנהיג של הג׳אם (אלבומים 401 ו־470), להקת המוד של סוף שנות השבעים, ואחר כך הקים את הסטייל קאונסיל (אלבום 539), שניגנה סול, ג׳אז ופופ מתוחכם. בסוף שנות השמונים נראה היה שהקריירה שלו נגמרה: חברת התקליטים דחתה את אלבומו האחרון של הסטייל קאונסיל, והוא נשאר בלי חוזה. הוא התחיל מחדש בהופעות קטנות, והוציא אלבום סולו ראשון ב־1992. Wild Wood, שיצא ב־1993, הוא אלבום הסולו השני שלו, וזה שהחזיר אותו לגמרי לפסגה.''',
'''במקום פופ מלוטש, Wild Wood מביא רוק חם, אורגני ובוגר, בהשראת להקות של סוף שנות השישים כמו טראפיק, ובהשראת ניל יאנג וניק דרייק. יש בו גיטרות אקוסטיות וחשמליות, עוגב המונד, פסנתר ותופים חיים, והוא נשמע כמו להקה שמנגנת יחד בחדר כפרי. Sunflower הפותח הוא שיר אהבה מלא תשוקה, עם גיטרות חזקות ופזמון גדול. שיר הנושא, Wild Wood, הוא שיר אקוסטי שקט ומהפנט, על התמודדות עם תקופה קשה ועל מציאת הדרך החוצה מהיער. Has My Fire Really Gone Out? הוא שאלה כנה של מוזיקאי שתוהה אם עוד נשאר בו כוח, ו־Hung Up נוגה ויפה.''',
'''האלבום החזיר את ולר להצלחה גדולה בבריטניה, ובשנים הבאות הוא הפך לדמות אב של דור הבריטפופ, ולהקות כמו אואזיס ראו בו מקור השראה. מאז הוא ממשיך להוציא אלבומים ולהופיע, ומכונה בבריטניה "המודפאדר", אבי המודים.''',
'''שמעו את Wild Wood בשקט, באוזניות, ואחריו את Harvest של ניל יאנג (אלבום 245), ותשמעו את ההשראה. ואחר כך חזרו ל־All Mod Cons של הג׳אם (אלבום 401), כדי לשמוע איך התחיל.''',
], [
('Wild Wood', 'שיר אקוסטי שקט ומהפנט על תקופה קשה ועל מציאת הדרך החוצה מהיער.'),
('Sunflower', 'הפותח, שיר אהבה מלא תשוקה, עם גיטרות חזקות, עוגב ופזמון גדול.'),
('Has My Fire Really Gone Out?', 'שאלה כנה של מוזיקאי שתוהה אם עוד נשאר בו כוח, בקצב רוק חם.'),
])

add(736, [
'''האוטרס הם בעצם לוק היינס, זמר וכותב שירים לונדוני, חריף, ציני ומצחיק, שהקים את הלהקה בתחילת שנות התשעים עם חברתו, הבסיסטית אליס רידמן, ועם המתופף גלן קולינס. היינס אהב את הגלאם של שנות השבעים, את הוולווט אנדרגראונד (אלבום 91) ואת בואי, ושנא כמעט כל דבר אחר במוזיקה הבריטית של זמנו. New Wave, אלבום הבכורה שלהם, יצא ב־1993, וזכה לביקורות נלהבות. הוא היה מועמד לפרס מרקורי, והפסיד, לפי הסיפור המפורסם, בהפרש קטן מאוד לאלבום של סוויד (אלבום 733).''',
'''המוזיקה עדינה, מלודית ומלאה באווירה: גיטרות אקוסטיות וחשמליות נקיות, צ׳לו מלנכולי, פסנתר ותופים רכים, והקול השקט והמעט מתנשא של היינס, שמספר סיפורים קטנים על אנשים בשולי עולם הבידור. השירים עוסקים בתהילה, בכישלון, בחלומות על כוכבות, בבגדים מחנויות יד שנייה ובכוכבי עבר שנשכחו. Show Girl הפותח הוא סיפור אהבה מריר ויפה על רקדנית, ו־American Guitars הוא שיר ציני ומצחיק על התשוקה הבריטית לרוק אמריקאי. Bailed Out ו־Junk Shop Clothes קליטים ושנונים, ו־Starstruck נוגה ומלא געגוע.''',
'''למרות השבחים, האוטרס לא הפכו ללהקה גדולה. היינס תמיד הרגיש זר לבריטפופ, ובשנים מאוחרות יותר כתב על התקופה ספר זיכרונות מצחיק ומלא עקיצות. New Wave נחשב היום לאחד האוצרות הנסתרים של הרוק הבריטי של שנות התשעים.''',
'''שמעו את Show Girl ואחריו את Suede (אלבום 733), שני אלבומי הבכורה שהתחרו על אותו פרס, ושימו לב כמה הם שונים: האחד רועש ודרמטי, והשני שקט, צנוע ועוקצני.''',
], [
('Show Girl', 'הפותח, סיפור אהבה מריר ויפה על רקדנית, עם גיטרות נקיות ושירה שקטה.'),
('American Guitars', 'שיר ציני ומצחיק על התשוקה הבריטית לרוק אמריקאי, בקצב קליל וקליט.'),
('Junk Shop Clothes', 'שיר שנון וקליט על בגדים מחנויות יד שנייה ועל חלומות של כוכבות.'),
])

add(737, [
'''ליז פייר גדלה בפרבר אמיד של שיקגו, למדה אמנות בקולג׳, ובתחילת שנות התשעים הקליטה בחדר שלה קלטות ביתיות של שירים עם גיטרה, שעברו מיד ליד בין חברים. היא חיה בתוך סצנת האינדי של שיקגו, עולם שנשלט על ידי גברים, מוזיקאים ומבקרים, שהיא כינתה בלגלוג "גייוויל". Exile in Guyville, אלבום הבכורה שלה, יצא ב־1993 בחברת התקליטים מטאדור, והיא הציגה אותו כתשובה, שיר אחרי שיר, לאלבום הכפול המפורסם של הרולינג סטונס, Exile on Main St. (אלבום 269).''',
'''האלבום ארוך, שמונה עשר שירים, ומרגיש כמו יומן אישי. הצליל פשוט וחשוף: גיטרה חשמלית או אקוסטית, בס, תופים מינימליים, וקול נמוך, שטוח ושקט, שכמעט מדבר. אבל המילים חדות, מצחיקות, כועסות ונוקבות, ועוסקות באהבה, בסקס, בגברים, בבדידות וברצון להיות מובנת. 6'1" הפותח הוא שיר רוק קצבי ובטוח בעצמו, ו־Never Said מתוק וקליט, עם פזמון של הכחשה שובבה. Divorce Song מספר על זוג שנפרד בזמן טיול, ו־Mesmerizing ו־Stratford-On-Guy יפים ומהפנטים. Fuck and Run עצוב וכן, על הרצון במשהו יציב ואמיתי.''',
'''Exile in Guyville נבחר על ידי מבקרים רבים לאלבום השנה, והפך לאחד האלבומים החשובים של האינדי רוק האמריקאי. הכנות שלו, והדרך שבה אישה צעירה דיברה בו בגלוי על תשוקה ועל כעס, השפיעו על דור שלם של זמרות וכותבות שבאו אחריה.''',
'''הקשיבו למילים, וחזרו אחר כך ל־Exile on Main St. של הרולינג סטונס (אלבום 269), ונסו לשמוע את הדיאלוג בין שני האלבומים, הגברי והנשי.''',
], [
('Never Said', 'שיר מתוק וקליט, עם פזמון של הכחשה שובבה וגיטרה פשוטה ומקפצת.'),
('6\'1"', 'הפותח, רוק קצבי ובטוח בעצמו, על אישה שעומדת זקוף מול גבר שאכזב אותה.'),
('Divorce Song', 'סיפור עצוב ומדויק על זוג שנפרד בזמן טיול, בגיטרה אקוסטית שקטה.'),
])

add(738, [
'''האפגן וויגס קמו בסינסינטי באמצע שנות השמונים, סביב הזמר והגיטריסט גרג דולי. הם התחילו כלהקת רוק רועשת בחברת סאב פופ, אותה חברה מסיאטל שהוציאה את התקליטים הראשונים של נירוונה, אבל ההבדל שלהם היה האהבה לסול ולמוזיקה שחורה של שנות השישים והשבעים. Gentlemen, שיצא ב־1993, היה האלבום הראשון שלהם בחברת תקליטים גדולה, והוא הוקלט באולפני ארדנט בממפיס, האולפן שבו הקליטה ביג סטאר (אלבום 242).''',
'''Gentlemen הוא אלבום אפל, כועס ומלא חרטה, על מערכת יחסים הרסנית, ועל גבר שיודע שהוא מתנהג רע, ולא מצליח להפסיק. דולי שר בקול צרוד, מיוסר ומלא תשוקה, והלהקה מנגנת רוק כבד עם גרוב של סול: גיטרות חזקות ומתפתלות, בס עמוק, ופסנתר ועוגב ברגעים השקטים. If I Were Going הפותח רך ומבשר רעות, ושיר הנושא מתפרץ בכעס. Debonair הוא השיר המפורסם, עם ריף גיטרה מצוין וקצב סול חזק ומקפץ. ב־My Curse שרה הזמרת מארסי מייס, שמביאה את הצד של האישה לסיפור, בקול כואב ושבור.''',
'''האלבום זכה לשבחים רבים, ונחשב עד היום ליצירת המופת של הלהקה. הוא הביא לרוק האלטרנטיבי של שנות התשעים משהו שכמעט לא היה בו קודם: חושניות, רגש של סול, ומבט כן ולא נעים על הצד האפל של הגבריות.''',
'''שמעו את Debonair, ואחריו את Gentlemen ואת My Curse, ותבינו את הסיפור. ואחר כך שמעו את Dusty in Memphis (אלבום 150), כדי לשמוע את הסול של ממפיס שדולי כל כך אהב.''',
], [
('Debonair', 'השיר המפורסם, ריף גיטרה מצוין וקצב סול, על גבר שיודע שהוא מתנהג רע.'),
('Gentlemen', 'שיר הנושא, מתפרץ בכעס ובחרטה, עם גיטרות חזקות וקול צרוד ומיוסר.'),
('My Curse', 'הזמרת מארסי מייס שרה את הצד של האישה בסיפור, בקול כואב ושבור.'),
])

add(739, [
'''איימי מאן התפרסמה בשנות השמונים כזמרת ובסיסטית של להקת הפופ טיל טיוזדיי, עם הלהיט Voices Carry. אחרי שהלהקה התפרקה, היא נאבקה במשך שנים עם חברות תקליטים, שלא הבינו את השירים שלה ולא נתנו לה להוציא אותם. Whatever, אלבום הסולו הראשון שלה, יצא לבסוף ב־1993 בחברה קטנה, בהפקתו של ג׳ון בריון, מוזיקאי מוכשר שניגן בעצמו בכלים רבים, והפך מאוחר יותר לאחד המפיקים החשובים בלוס אנג׳לס.''',
'''המוזיקה היא פופ רוק חם וקלאסי, בהשראת הביטלס, הבירדס ושירי הפופ של שנות השישים: גיטרות מצלצלות, קלידים, פסנתר, הרמוניות קוליות, ומנגינות פשוטות ויפות. הקול של מאן נקי, שקט ומעט עצוב, והמילים חכמות, עוקצניות ומלאות אירוניה, על אהבה, על אכזבה ועל אנשים שמשקרים לעצמם ולאחרים. I Should've Known הפותח הוא שיר פרידה מר ושנון, עם גיטרות חזקות. 4th of July הוא שיר עצוב ויפה על יום חג בלי שמחה, ו־Fifty Years After the Fair חולמני ונוגה, עם גיטרת שתים עשרה מיתרים של רוג׳ר מקגווין מהבירדס. Stupid Thing ו־Say Anything קליטים ומרירים.''',
'''Whatever לא נמכר הרבה, אבל זכה לשבחים רבים, והפך את מאן לאחת הכותבות המוערכות של התקופה. כמה שנים אחר כך היא כתבה שירים לסרט מגנוליה, שהביאו לה מועמדות לאוסקר.''',
'''שמעו את 4th of July בשקט, ואחריו את Mr. Tambourine Man של הבירדס (אלבום 57), ותשמעו את ההשראה. ושימו לב לגיטרה המצלצלת של מקגווין עצמו ב־Fifty Years After the Fair.''',
], [
('I Should\'ve Known', 'הפותח, שיר פרידה מר ושנון, עם גיטרות חזקות ופזמון גדול וקליט.'),
('4th of July', 'שיר עצוב ויפה על יום חג בלי שמחה, בקול שקט ועייף.'),
('Fifty Years After the Fair', 'שיר חולמני ונוגה, עם גיטרת שתים עשרה מיתרים של רוג׳ר מקגווין.'),
])

add(740, [
'''גרנט לי באפלו הייתה שלישייה מלוס אנג׳לס, סביב הזמר וכותב השירים גרנט־לי פיליפס, עם הבסיסט פול קימבל, שהפיק גם את האלבום, והמתופף ג׳ואי פיטרס. פיליפס, שגדל בסטוקטון שבקליפורניה ואהב את המסורת האמריקאית הישנה, כתב שירים על ההיסטוריה של אמריקה, על החלומות שלה ועל השקרים שלה. Fuzzy, אלבום הבכורה שלהם, יצא ב־1993, ולמרות שלא נמכר הרבה, הוא זכה לשבחים חמים ממוזיקאים אחרים. מייקל סטייפ מ־R.E.M. אמר עליו שהוא האלבום הטוב ביותר של השנה.''',
'''המוזיקה מחברת בין פולק אמריקאי ישן, קאנטרי ורוק, לבין גיטרות חשמליות גדולות ורועשות ודרמה של גלאם. פיליפס מנגן בגיטרה אקוסטית בעלת שנים עשר מיתרים, ושר בקול גבוה, חם ומלא רגש, שמזכיר לפעמים זמרים של פעם. The Shining Hour הפותח רך ויפה, ו־Jupiter and Teardrop הוא שיר מרחף ומלא געגוע. שיר הנושא, Fuzzy, איטי, חלומי ועצוב. America Snoring הוא שיר מחאה חזק ורועש, על אמריקה שישנה בזמן שהעולם בוער, ו־Stars n' Stripes מסתכל במבט מריר על הדגל ועל המולדת. Dixie Drug Store פרוע ושמח.''',
'''Fuzzy פתח את הדרך לשני אלבומים נוספים של הלהקה, שזכו גם הם להערכה, ואחר כך המשיך פיליפס בקריירת סולו ארוכה. האלבום נחשב לאחד האלבומים המוקדמים של מה שנקרא אחר כך "אמריקנה", המוזיקה שמחברת את הרוק עם השורשים הישנים של אמריקה.''',
'''שמעו את Jupiter and Teardrop באוזניות, ושימו לב לגיטרה האקוסטית. ואחר כך שמעו את Automatic for the People של R.E.M. (אלבום 718), שהשפיע מאוד על הלהקה.''',
], [
('Jupiter and Teardrop', 'שיר מרחף ומלא געגוע, עם גיטרה אקוסטית רחבה וקול גבוה וחם.'),
('America Snoring', 'שיר מחאה חזק ורועש על אמריקה שישנה בזמן שהעולם בוער סביבה.'),
('Fuzzy', 'שיר הנושא, איטי, חלומי ועצוב, עם קול רך שמתרומם לאט.'),
])

add(741, [
'''אחרי ההצלחה העצומה של Nevermind (אלבום 685), נירוונה הפכה ללהקה המפורסמת בעולם, וקורט קוביין, הזמר והכותב, התקשה מאוד להתמודד עם התהילה, עם התקשורת ועם הציפיות. הוא הרגיש ש־Nevermind יצא מלוטש מדי, ולאלבום הבא רצה צליל גולמי וקשה. הלהקה בחרה במפיק סטיב אלביני, הידוע בהקלטות ישירות ורועשות, והקליטה את In Utero באולפן קטן במינסוטה, בתוך שבועיים בלבד. האלבום יצא בספטמבר 1993, אחרי ויכוחים עם חברת התקליטים, שחששה שהוא קשה מדי לשמיעה.''',
'''הצליל של In Utero חשוף, מחוספס ואגרסיבי יותר: תופים חזקים וטבעיים של דייב גרוהל, בס עבה של קריסט נובוסליק, וגיטרה שעוברת משקט לצעקה, יחד עם קולו של קוביין, שבור ועצבני. אבל לצד הרעש יש כאן גם מנגינות יפות במיוחד. Heart-Shaped Box הוא שיר אפל ומהפנט, עם בתים שקטים ופזמון מתפוצץ. Serve the Servants הפותח מדבר בכנות על התהילה ועל המשפחה. Dumb הוא שיר שקט ונוגה עם צ׳לו, ו־All Apologies, הסוגר, הוא שיר רך ומרגש עם צ׳לו וגיטרה, שנשמע כמו פרידה. Pennyroyal Tea פשוט ועצוב, ו־Scentless Apprentice ו־Milk It רועשים ופרועים.''',
'''In Utero הגיע למקום הראשון במצעד האמריקאי, ונחשב לאחד האלבומים החשובים של שנות התשעים. זה היה האלבום האחרון של נירוונה באולפן: קוביין מת באפריל 1994, כחצי שנה אחרי צאתו.''',
'''שמעו את All Apologies, ואחריו את Surfer Rosa של הפיקסיז (אלבום 623), שגם אותו הקליט אלביני, ושקוביין אהב מאוד, ותשמעו את ההשראה לצליל של In Utero.''',
], [
('Heart-Shaped Box', 'שיר אפל ומהפנט, בתים שקטים ומאיימים ופזמון שמתפוצץ בבת אחת.'),
('All Apologies', 'הסוגר, שיר רך ומרגש עם צ׳לו וגיטרה, שנשמע היום כמו פרידה.'),
('Dumb', 'שיר שקט ונוגה עם צ׳לו, על אושר פשוט של מי שאולי לא מבין הכל.'),
])

add(742, [
'''ג׳מירוקוואי הם בעיקר ג׳יי קיי, זמר ורקדן לונדוני צעיר עם כובעים מוזרים וגדולים, שהקים להקה סביב האהבה שלו לפאנק, לסול ולג׳אז של שנות השבעים, ובמיוחד לסטיבי וונדר. הוא גדל עם אמו, זמרת ג׳אז, בתנאים לא קלים, וחלם להיות כוכב. הסינגל הראשון שלהם יצא בחברה קטנה בשם אסיד ג׳אז, שנתנה את שמה לסגנון כולו, ומיד אחר כך הוא חתם על חוזה ענק לשמונה אלבומים. Emergency on Planet Earth, אלבום הבכורה, יצא ב־1993.''',
'''המוזיקה חמה, קצבית ומלאה בכלים חיים: בס גמיש ומקפץ, כלי נשיפה, קלידים חשמליים, כלי מיתר, ודיג׳רידו, כלי הנשיפה העתיק של אוסטרליה, שמוסיף צליל עמוק ומוזר. הקול של ג׳יי קיי גמיש וחם, והוא מושפע מאוד מסטיבי וונדר. המילים עוסקות לא פעם באיכות הסביבה, בשלום ובצדק, נושאים שהיו חשובים לו מאוד. When You Gonna Learn הוא שיר מחאה קצבי וסוחף על הנזק שבני האדם עושים לכדור הארץ, עם דיג׳רידו בפתיחה. Too Young to Die הוא שיר נגד מלחמה, עם גרוב חלק ומלודיה יפה, ו־Blow Your Mind ארוך ומרחף, עם קטעי ג׳אז מאולתרים. Emergency on Planet Earth, שיר הנושא, שמח ורקיד.''',
'''האלבום הגיע למקום הראשון במצעד הבריטי, ופתח לג׳מירוקוואי קריירה ארוכה ומוצלחת, עם להיטים גדולים בכל העולם. הוא עזר להחזיר את הפאנק והסול של שנות השבעים למצעדים של שנות התשעים.''',
'''שמעו את When You Gonna Learn ואחריו את Innervisions של סטיבי וונדר (אלבום 292), ותשמעו בדיוק מאיפה ג׳יי קיי קיבל את ההשראה, גם בקול וגם במסר.''',
], [
('When You Gonna Learn', 'שיר מחאה קצבי וסוחף על כדור הארץ, שנפתח בדיג׳רידו עמוק ומוזר.'),
('Too Young to Die', 'שיר נגד מלחמה, עם גרוב חלק, כלי מיתר ומלודיה יפה וחמה.'),
('Blow Your Mind', 'שיר ארוך ומרחף, עם בס גמיש וקטעי ג׳אז מאולתרים באמצע.'),
])

add(743, [
'''הפט שופ בויז, ניל טננט וכריס לואו, היו כבר אחד מצמדי הפופ המצליחים של בריטניה, עם אלבומים כמו Actually (אלבום 607) ו־Behaviour (אלבום 672). Behaviour היה אלבום שקט, בוגר ונוגה, ול־Very, שיצא ב־1993, הם רצו לחזור לפופ צבעוני, קצבי ושמח. העטיפה של התקליטור הייתה קופסה כתומה מפלסטיק עם בליטות קטנות, כמו לבנת לגו, אחד מעיצובי העטיפות המפורסמים של התקופה. שנה אחר כך טננט גם סיפר בגלוי, בראיון, על היותו גיי.''',
'''המוזיקה עשירה, דרמטית ומלאה בצבעים: סינתיסייזרים גדולים, תזמורות, מקהלות, קצבי ריקוד, וקולו הקריר, האירוני והמנומס של טננט. מתחת לפופ העליז יש הרבה מילים חכמות, עצובות ואישיות, על אהבה, על פחד, על בדידות ועל גברים שמסתירים את מי שהם. Can You Forgive Her? הפותח הוא שיר דרמטי ומבריק על גבר שאהובתו לועגת לו. Liberation רך ויפה, על התאהבות. Go West, גרסה לשיר הדיסקו של הוויליג׳ פיפל, הופך את השיר המקורי להמנון ענק עם מקהלה גברית, ומוסיף לו נגיעה של עצב. Dreaming of the Queen מעורר מחשבה ונוגה.''',
'''Very היה האלבום הראשון שלהם שהגיע למקום הראשון במצעד הבריטי, ו־Go West הפך לאחד הלהיטים הגדולים שלהם ולשיר שמושר עד היום באצטדיוני כדורגל. רבים רואים בו את פסגת הפופ של הצמד.''',
'''שמעו את Can You Forgive Her? ואת Go West בווליום גבוה. ואחר כך שמעו את Behaviour (אלבום 672), ותשמעו כמה שונים שני האלבומים, אף שיצאו בהפרש של שלוש שנים בלבד.''',
], [
('Go West', 'גרסה לשיר דיסקו של הוויליג׳ פיפל, המנון ענק עם מקהלה גברית ונגיעה של עצב.'),
('Can You Forgive Her?', 'הפותח, שיר דרמטי ומבריק על גבר שאהובתו לועגת לו ולסודותיו.'),
('Liberation', 'שיר רך ויפה על התאהבות, עם כלי מיתר וקול חם וחולמני.'),
])

add(744, [
'''אחרי ההצלחה של Dry (אלבום 732), פי. ג׳יי. הארווי חתמה בחברת תקליטים גדולה, ולאלבום השני שלה בחרה במפיק סטיב אלביני, הידוע בהקלטות ישירות, רועשות ובלי קישוטים. Rid of Me הוקלט במהירות באולפן קטן במינסוטה, אותו אולפן שבו הקליטה נירוונה כמה חודשים אחר כך את In Utero (אלבום 741), ויצא ב־1993. זה היה האלבום האחרון של השלישייה המקורית, עם רוב אליס בתופים וסטיב וון בבס.''',
'''הצליל קשה ומטלטל: רגעים שקטים מאוד, שבהם בקושי שומעים את הקול, ופתאום פיצוצים של רעש, תופים ענקיים וגיטרות שורטות. אלביני הקליט את הכלים כמו שהם, בלי ליטוש, והתוצאה נשמעת כמו הופעה בחדר קטן. המילים עוסקות בתשוקה, בקנאה, בנקמה ובכוח בין גברים לנשים, בעוצמה ובאירוניה. Rid of Me, שיר הנושא, מתחיל בלחישה מאיימת ומתפוצץ בצעקות. 50ft Queenie הוא שיר מהיר, מצחיק ופרוע, שבו הארווי מכריזה שהיא הגדולה בעולם. Man-Size מופיע פעמיים: פעם עם רביעיית כלי מיתר, ופעם עם הלהקה. ויש גם גרסה פרועה ל־Highway 61 Revisited של בוב דילן (אלבום 58).''',
'''Rid of Me נחשב לאחד האלבומים החזקים והאמיצים של הרוק בשנות התשעים, והוכיח שהארווי היא אמנית שלא מוכנה להתפשר. אחריו היא פירקה את השלישייה, והמשיכה לשנות את הצליל שלה כמעט בכל אלבום.''',
'''זה אלבום להאזנה בריכוז, עם הרבה שקט ורעש. שמעו את Rid of Me עד הסוף. ואחר כך שמעו את Highway 61 Revisited של בוב דילן (אלבום 58), והשוו בין שתי הגרסאות.''',
], [
('Rid of Me', 'שיר הנושא, מתחיל בלחישה מאיימת ומתפוצץ בצעקות ובתופים ענקיים.'),
('50ft Queenie', 'שיר מהיר, מצחיק ופרוע, שבו הארווי מכריזה שהיא הגדולה בעולם.'),
('Highway 61 Revisited', 'גרסה פרועה ומעוותת לשיר של בוב דילן, עם גיטרה צורמת וקול חד.'),
])

add(745, [
'''בלר קמו בלונדון בסוף שנות השמונים, סביב הזמר דיימון אלברן, הגיטריסט גרהם קוקסון, הבסיסט אלכס ג׳יימס והמתופף דייב ראונטרי. אלבום הבכורה שלהם הצליח, אבל אחריו הגיעו חובות, סיבוב הופעות אומלל בארצות הברית, וגעגוע גדול הביתה. אלברן חזר לבריטניה כועס על האמריקניזציה של התרבות הבריטית, והחליט לכתוב שירים על אנגליה עצמה: על הפרברים, על הפרסומות, על הרכבות ועל האנשים הרגילים. Modern Life Is Rubbish, שפירושו "החיים המודרניים הם זבל", יצא ב־1993, בהפקתו של סטיבן סטריט, שהפיק קודם את הסמית׳ס.''',
'''המוזיקה מחברת בין הפופ הבריטי של שנות השישים, ובמיוחד הקינקס (אלבום 110), לבין הגיטרות הרועשות והמשונות של קוקסון. יש כאן הרבה הומור, דמויות קטנות וסיפורים, ומבטא לונדוני מודגש. For Tomorrow הפותח הוא שיר יפה וגדול על זוג צעיר בלונדון, עם מקהלת "לה לה לה" ותחושה של יום אפור ומלא תקווה. Chemical World הוא שיר רוק מלודי ומלא געגוע, ו־Sunday Sunday שמח ומצחיק, על יום ראשון אנגלי טיפוסי, עם ארוחה משפחתית וטיול בפארק. Colin Zeal מספר על אדם שתמיד מגיע בזמן, ו־Advert הוא שיר מהיר וזועם על פרסומות.''',
'''האלבום לא נמכר הרבה בזמנו, אבל הוא נחשב לנקודת ההתחלה האמיתית של הבריטפופ, ושל הדרך שבה בלר הפכו לאחת הלהקות הגדולות בבריטניה. האלבום הבא שלהם, Parklife, הפך אותם לכוכבים, אבל הכל התחיל כאן.''',
'''שמעו את For Tomorrow ואחריו את Waterloo Sunset מתוך Something Else של הקינקס (אלבום 97), ותשמעו את ההשראה: שני שירים על לונדון, על אהבה ועל אנשים רגילים.''',
], [
('For Tomorrow', 'הפותח, שיר יפה וגדול על זוג צעיר בלונדון, עם מקהלת "לה לה לה".'),
('Chemical World', 'שיר רוק מלודי ומלא געגוע, עם גיטרות חזקות ופזמון שקל לשיר.'),
('Sunday Sunday', 'שיר שמח ומצחיק על יום ראשון אנגלי טיפוסי, עם ארוחה משפחתית וטיול.'),
])

add(746, [
'''שריל קרואו גדלה בעיירה קטנה במיזורי, הייתה מורה למוזיקה בבית ספר יסודי, ועברה ללוס אנג׳לס כדי להפוך לזמרת. בסוף שנות השמונים היא הייתה זמרת ליווי בסיבוב ההופעות הגדול של מייקל ג׳קסון, ואחר כך הקליטה אלבום סולו ראשון, שחברת התקליטים החליטה לגנוז. אז היא הצטרפה לחבורה של מוזיקאים, ביניהם המפיק ביל בוטרל, קווין גילברט ודייוויד בארוולד, שנפגשו כל יום שלישי בערב באולפן של בוטרל, כדי לנגן, לשתות ולכתוב שירים יחד. מתוך הערבים האלה נולד Tuesday Night Music Club, שיצא ב־1993.''',
'''המוזיקה היא רוק אמריקאי נינוח וחם, עם השפעות של קאנטרי, בלוז, פולק ופופ: גיטרות אקוסטיות וחשמליות, אורגן, תופים רגועים, וקולה המחוספס והידידותי של קרואו. All I Wanna Do, הלהיט הגדול, הוא שיר קליל ומצחיק על יום שתייה בבר בצהריים, שהמילים שלו מבוססות על שיר של המשורר ווין קופר. Strong Enough הוא שיר אקוסטי רך ושקט על אהבה ועל חולשה. Leaving Las Vegas מספר על עזיבת עיר האורות, ו־Run, Baby, Run הפותח הוא שיר יפה על ילדה שגדלה בשנות השישים. Can't Cry Anymore בלוזי וכואב.''',
'''האלבום נמכר במיליוני עותקים, וזכה בשלושה פרסי גראמי, כולל פרס האמנית החדשה הטובה ביותר. אחרי ההצלחה היו ויכוחים בין קרואו לבין חלק מחברי החבורה, שהרגישו שהקרדיט לא חולק כראוי. קרואו המשיכה לקריירה ארוכה ומצליחה מאוד.''',
'''זה אלבום טוב לנסיעה ארוכה ביום שמש. שמעו את Strong Enough בשקט, ואחריו את Tapestry של קרול קינג (אלבום 211), עוד אלבום של כותבת שהפכה לכוכבת.''',
], [
('All I Wanna Do', 'הלהיט, שיר קליל ומצחיק על יום שתייה בבר, עם מילים מתוך שיר של משורר.'),
('Strong Enough', 'שיר אקוסטי רך ושקט על אהבה ועל חולשה, בקול חם ומחוספס.'),
('Run, Baby, Run', 'הפותח, שיר יפה ומלא געגוע על ילדה שגדלה בשנות השישים.'),
])

add(748, [
'''הוו־טאנג קלאן הם קבוצה של תשעה ראפרים מסטטן איילנד שבניו יורק, רובם בני דודים וחברי ילדות, שהתאחדו סביב המפיק והראפר RZA. כולם אהבו סרטי קונג פו ישנים מהונג קונג, ולקחו מהם את השמות, את הדימויים ואת הפילוסופיה, ואפילו כינו את השכונה שלהם "שאולין", על שם המנזר המפורסם. Enter the Wu-Tang (36 Chambers), אלבום הבכורה שלהם, יצא בסוף 1993. RZA השיג להם חוזה מיוחד במינו: כל חבר בקבוצה היה חופשי לחתום כסולן בכל חברת תקליטים שירצה, וכך הוא בנה אימפריה שלמה של אלבומים בשנים שאחריו.''',
'''הצליל מחוספס, אפל וגולמי: קצבים יבשים וכבדים, דגימות של פסנתר, של סול ישן ושל דיאלוגים מתוך סרטי קונג פו, בלי שום ליטוש. על הקצבים האלה מחליפים ביניהם תשעה קולות שונים לגמרי: מת׳וד מן הכריזמטי, גוסטפייס קילה וראקוון המהירים, אינספקטה דק החד, ג׳יזה הקר והמחושב, ואול דרטי בסטרד, הפרוע והבלתי צפוי. C.R.E.A.M. הוא שיר עצוב ומהורהר על עוני ועל כסף, מעל פסנתר סול יפה. Protect Ya Neck, הסינגל הראשון, הוא תחרות של כולם, אחד אחרי השני. Method Man הוא הצגה של כוכב צעיר, ו־Da Mystery of Chessboxin' מחבר בין שחמט לבין קרבות.''',
'''האלבום נחשב לאחד האלבומים החשובים בתולדות ההיפ הופ, ושינה את הצליל של ההיפ הופ של ניו יורק. הוא הוביל לשורה של אלבומי סולו מצליחים של חברי הקבוצה, והשפיע על אינספור ראפרים ומפיקים.''',
'''שמעו את C.R.E.A.M., ושימו לב לפסנתר העצוב. ואחר כך שמעו את It Takes a Nation of Millions של פבליק אנמי (אלבום 634), עוד היפ הופ ניו יורקי קשה ורועש.''',
], [
('C.R.E.A.M.', 'שיר עצוב ומהורהר על עוני ועל כסף, מעל פסנתר סול יפה ונוגה.'),
('Protect Ya Neck', 'הסינגל הראשון, תחרות של כל חברי הקבוצה, אחד אחרי השני.'),
('Method Man', 'הצגה מבריקה ומצחיקה של כוכב צעיר, עם קצב כבד ופזמון קליט.'),
])

add(749, [
'''ביורק גוומונדסדוטיר מאיסלנד הייתה כוכבת עוד בילדותה, כשהוציאה אלבום ראשון בגיל אחת עשרה, ואחר כך שרה בכמה להקות פאנק, עד שהתפרסמה בעולם כזמרת הסוגרקיובס (אלבום 631). אחרי שהלהקה התפרקה היא עברה ללונדון, והתאהבה במוזיקה האלקטרונית ובתרבות המועדונים של העיר. את Debut, שיצא ב־1993, הפיקה יחד עם נלי הופר, שעבד קודם עם סול טו סול ועם מסיב אטאק (אלבום 703). רבים מהשירים כתבה עוד בילדותה ובנעוריה, ושמרה אותם לזמן הנכון.''',
'''המוזיקה מחברת בין פופ, האוס, ג׳אז ומוזיקה עולמית: קצבי ריקוד, נבל, כלי מיתר, טבלה הודית, סקסופונים ומכונות תופים, ומעל הכל הקול המיוחד של ביורק, שיכול ללחוש כמו ילדה ולצעוק כמו סערה. Human Behaviour הפותח הוא שיר מוזר ומקסים על בני אדם, מנקודת מבט של חיה. Venus as a Boy הוא שיר אהבה רך וחושני, עם כלי מיתר וטבלה. Big Time Sensuality ו־Violently Happy שמחים ורוקדים, ו־There's More to Life Than This הוקלט, לפי הסיפור, בשירותים של מועדון לילה, כשרעש המסיבה נשמע ברקע. Like Someone in Love הוא שיר ג׳אז ישן, עם נבל בלבד.''',
'''Debut נמכר במיליוני עותקים, והפך את ביורק לכוכבת עולמית ולאחת האמניות המקוריות והמשפיעות של העשורים האחרונים. הוא הראה שמוזיקה אלקטרונית יכולה להיות חמה, אישית ומלאת רגש.''',
'''שמעו את Venus as a Boy ואת Like Someone in Love, ושימו לב לטווח של הקול. ואחר כך שמעו את Life's Too Good (אלבום 631), כדי לשמוע מאיפה היא באה.''',
], [
('Human Behaviour', 'הפותח, שיר מוזר ומקסים על בני האדם, כפי שהם נראים בעיני חיה.'),
('Venus as a Boy', 'שיר אהבה רך וחושני, עם כלי מיתר, טבלה הודית וקול לוחש.'),
('Big Time Sensuality', 'שיר ריקוד שמח ומלא חיים, על התחלה של אהבה גדולה ומפחידה.'),
])

add(750, [
'''אורביטל הם שני אחים מקנט, בדרום־מזרח אנגליה, פול ופיל הרטנול, שהתאהבו בסוף שנות השמונים בתרבות מסיבות האסיד האוס. את השם לקחו מהכביש הטבעתי הגדול סביב לונדון, ה־M25, שלאורכו נערכו אז רבות מהמסיבות הגדולות. כבר הסינגל הראשון שלהם, Chime, שהקליטו בבית על ציוד פשוט, הפך ללהיט. האלבום השני שלהם, שיצא ב־1993, נקרא פשוט Orbital, כמו הראשון, אבל כולם מכנים אותו "האלבום החום", על שם צבע העטיפה.''',
'''זו מוזיקה אלקטרונית לריקוד ולהאזנה בבית גם יחד: קטעים ארוכים, שנבנים לאט לאט משכבות של סינתיסייזרים, קצבים ומנגינות, ומשתנים כל הזמן, כמו מסע. אין כאן כמעט שירה, אבל יש הרבה רגש: שמחה, עצב, מתח ושלווה. Time Becomes הפותח הוא קטע קצר ומבלבל של קול שחוזר על עצמו. Lush 3-1 ו־Lush 3-2 עולים ומתרוממים, עם מנגינות זוהרות. Impact (The Earth Is Burning) מהיר ומתוח, ו־Halcyon + On + On, אולי הקטע המפורסם שלהם, הוא קטע יפה, מרחף ומרגש, עם קול נשי שמסתובב וחוזר, שהאחים הקדישו לאמם.''',
'''האלבום נחשב לאחד האלבומים החשובים של המוזיקה האלקטרונית הבריטית. ב־1994 הופיעו אורביטל בפסטיבל גלסטונברי, באחת ההופעות המפורסמות בתולדות הפסטיבל, שהוכיחה שמוזיקה אלקטרונית יכולה להצליח על במה גדולה, מול קהל של רוק.''',
'''שמעו את Halcyon + On + On באוזניות, ותנו לו להתפתח לאט. ואחר כך שמעו את Selected Ambient Works 85–92 של אייפקס טווין (אלבום 708), מאותה תקופה, אבל שקט ואינטימי יותר.''',
], [
('Halcyon + On + On', 'קטע יפה, מרחף ומרגש, עם קול נשי שחוזר, שהאחים הקדישו לאמם.'),
('Lush 3-1', 'קטע שעולה ומתרומם לאט, עם מנגינות זוהרות וקצב שמח ומקפץ.'),
('Impact (The Earth Is Burning)', 'קטע מהיר ומתוח, עם קצב חזק וסינתיסייזרים שמתנגשים זה בזה.'),
])
